('59b7b6da-0715-5ef6-8d62-8df2ffbb126a','18cf2f66-8eca-5ee2-8f83-c69221d522f4',1,'noun','A2','S1','W1',null,'[{"phrase":"get off the ground","register":null,"definition_en":"to start to be successful","translation":"برای شروع موفق بودن","example":"Her show never really got off the ground in the UK.","example_translation":"نمایش او هرگز در بریتانیا اجرا نشد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785766.mp3"},{"phrase":"gain ground","register":null,"definition_en":"to make steady progress and become more popular , more successful etc","translation":"برای پیشرفت مداوم و محبوب تر شدن، موفقیت بیشتر و غیره","example":"The anti-smoking lobby has steadily gained ground in the last decade.","example_translation":"لابی ضد سیگار در دهه گذشته به طور پیوسته جایگاه خود را به دست آورده است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001318239.mp3"},{"phrase":"lose ground","register":null,"definition_en":"to become less successful compared with someone or something you are competing with","translation":"در مقایسه با کسی یا چیزی که با آن رقابت می کنید کمتر موفق شوید","example":"The Indian team seem determined to regain the ground they lost in the last game.","example_translation":"به نظر می رسد که تیم هند مصمم است زمینی را که در بازی گذشته از دست داده بود، دوباره به دست آورد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785769.mp3"},{"phrase":"on the ground","register":null,"definition_en":"in the place or situation where something important is happening, rather than somewhere else – used especially in news reports","translation":"در مکان یا موقعیتی که اتفاق مهمی در حال رخ دادن است، به جای جای دیگری - به ویژه در گزارش های خبری استفاده می شود","example":"While the politicians talk of peace, the situation on the ground remains tense.","example_translation":"در حالی که سیاستمداران از صلح صحبت می کنند، وضعیت در میدان همچنان متشنج است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001305375.mp3"},{"phrase":"stamping ground","register":"informal","definition_en":"someone’s stamping ground is an area where they are known or have a lot of influence","translation":"زمین مهر کسی منطقه ای است که در آن شناخته شده یا تأثیر زیادی دارد","example":"I guess he’ll try to reach his old stomping ground to drum up support.","example_translation":"","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785790.mp3"}]'::jsonb),
