('fc4d2cbb-5c2f-584c-9e7c-4e618ee898fc','04656b1f-ca73-5564-a65d-2d7543058809',1,'adjective','B1','S2','W2',null,'[{"phrase":"make a mental note","register":null,"definition_en":"to make a special effort to remember something","translation":"تلاش ویژه برای به خاطر سپردن چیزی","example":"Sarah made a mental note to ask Janine about it later.","example_translation":"سارا یادداشت ذهنی گذاشت تا بعداً در مورد آن از جنین بپرسد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001564224.mp3"},{"phrase":"mental block","register":null,"definition_en":"a difficulty in remembering something or in understanding something","translation":"مشکل در به خاطر سپردن چیزی یا درک چیزی","example":"I got a complete mental block as soon as the interviewer asked me a question.","example_translation":"به محض اینکه مصاحبه کننده از من سوالی پرسید، یک بلوک ذهنی کامل گرفتم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000222160.mp3"}]'::jsonb),
