('8755dc21-c8b3-58be-b58f-557dd671dc4c','98dd15c1-3bc1-51fb-87fd-d49e33373b07',1,'noun','A1','S1','W1','[ countable ]','[{"phrase":"the last minute","register":null,"definition_en":"the last possible time, just before it is too late","translation":"آخرین زمان ممکن، درست قبل از اینکه خیلی دیر شود","example":"He cancelled his trip to England at the last minute.","example_translation":"او در آخرین لحظه سفر خود به انگلیس را لغو کرد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000200040.mp3"},{"phrase":"by the minute","register":null,"definition_en":"used to say that something continues quickly becoming greater, stronger etc","translation":"می گفت که چیزی به سرعت بزرگتر، قوی تر و غیره ادامه می یابد","example":"She was getting angrier by the minute.","example_translation":"لحظه به لحظه عصبانی تر می شد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000200053.mp3"},{"phrase":"within minutes","register":null,"definition_en":"very soon after something has happened","translation":"خیلی زود پس از اتفاق افتادن چیزی","example":"The ambulance was there within minutes.","example_translation":"در عرض چند دقیقه آمبولانس آنجا بود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000200064.mp3"},{"phrase":"a minute","register":null,"definition_en":"a very short period of time","translation":"یک دوره زمانی بسیار کوتاه","example":"Sam thought for a minute, then smiled at his brother.","example_translation":"سام یک دقیقه فکر کرد و سپس به برادرش لبخند زد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001554290.mp3"},{"phrase":"this minute","register":null,"definition_en":"immediately","translation":"بلافاصله","example":"Johnny! Get inside, this minute!","example_translation":"جانی! همین لحظه داخل شو!","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001554299.mp3"},{"phrase":"the next minute","register":null,"definition_en":"immediately afterwards","translation":"بلافاصله پس از آن","example":"I put down the phone and the next minute it rang again.","example_translation":"گوشی را گذاشتم و لحظه بعد دوباره زنگ خورد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001840714.mp3"}]'::jsonb),
