('4a26256e-07ac-58f9-b490-50f0cc4c9537','2eef5c04-b3f3-59a7-8970-b95d4d31d717',1,'noun','A2','S3','W3','[ countable ]','[{"phrase":"a mirror of something","register":null,"definition_en":"something that gives a clear idea of what something else is like","translation":"چیزی که تصور روشنی از اینکه چیز دیگری چگونه است می دهد","example":"We believe the polls are an accurate mirror of public opinion.","example_translation":"ما معتقدیم که نظرسنجی ها آینه دقیق افکار عمومی هستند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000200371.mp3"}]'::jsonb),
