('0434c56f-744f-5a52-b97c-ee1276f46d22','8f05106a-1ee5-5039-9441-ddd33d045d56',1,'noun','A1','S1','W1','[ countable ]','[{"phrase":"at the moment","register":"especially spoken","definition_en":"now","translation":"اکنون","example":"Julia’s on holiday in Spain at the moment.","example_translation":"جولیا در حال حاضر در تعطیلات در اسپانیا است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000205770.mp3"},{"phrase":"for the moment","register":null,"definition_en":"used to say that something is happening or is true now but will probably change in the future","translation":"قبلاً می گفت چیزی در حال رخ دادن است یا واقعیت دارد اما احتمالاً در آینده تغییر خواهد کرد","example":"Well, for the moment we’re just friends.","example_translation":"خوب، در حال حاضر ما فقط دوست هستیم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000205775.mp3"},{"phrase":"the last moment","register":null,"definition_en":"if you do something at the last moment or if something happens at the last moment, it happens at the last possible time","translation":"اگر کاری را در آخرین لحظه انجام دهید یا اگر چیزی در آخرین لحظه اتفاق بیفتد، در آخرین زمان ممکن اتفاق می افتد","example":"The operation was cancelled at the last moment.","example_translation":"این عملیات در آخرین لحظه لغو شد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001648533.mp3"},{"phrase":"of the moment","register":null,"definition_en":"the person, idea, word etc of the moment is the one that is most important or popular at the present time","translation":"شخص، ایده، کلمه و غیره در لحظه همان چیزی است که در زمان حال مهم یا محبوب است","example":"They interview personalities on a topic of the moment.","example_translation":"آنها با شخصیت ها در مورد یک موضوع لحظه مصاحبه می کنند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000205836.mp3"},{"phrase":"be having a moment","register":"informal","definition_en":"to be having a time of success or popularity – used especially in magazines","translation":"داشتن زمان موفقیت یا محبوبیت - به ویژه در مجلات استفاده می شود","example":"Short hairstyles are having a moment.","example_translation":"مدل موی کوتاه لحظه ای دارد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00598.mp3"},{"phrase":"not a moment too soon","register":null,"definition_en":"almost too late","translation":"تقریبا خیلی دیر","example":"The ambulance finally arrived, and not a moment too soon.","example_translation":"بالاخره آمبولانس رسید و لحظه ای هم زود نبود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000205858.mp3"},{"phrase":"the moment of truth","register":null,"definition_en":"the time when you will find out if something will work properly, be successful etc","translation":"زمانی که متوجه خواهید شد که آیا چیزی به درستی کار می کند، موفق می شود و غیره","example":"","example_translation":"","example_audio_url":""},{"phrase":"of great moment","register":"old-fashioned","definition_en":"important","translation":"مهم است","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
