('70e5ec99-5181-5085-aa1b-c2349fd18fa0','6030e7b1-859a-50c0-9411-2e27071cf13c',1,'adjective','A2','S1','W1',null,'[{"phrase":"public service","register":null,"definition_en":"a service , such as transport or health care , that a government provides","translation":"خدماتی مانند حمل و نقل یا مراقبت های بهداشتی که دولت ارائه می کند","example":"efforts to improve quality in public services","example_translation":"تلاش برای بهبود کیفیت در خدمات عمومی","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270663.mp3"},{"phrase":"public life","register":null,"definition_en":"work that you do, especially for the government, that makes you well known to many people","translation":"کارهایی که انجام می دهید، به ویژه برای دولت، که شما را برای بسیاری از مردم به خوبی می شناسد","example":"Howard seems to have retired from public life.","example_translation":"به نظر می رسد هاوارد از زندگی عمومی بازنشسته شده است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270025.mp3"},{"phrase":"public image","register":null,"definition_en":"the public image of a famous person or organization is the character or attitudes that most people think they have","translation":"تصویر عمومی از یک فرد یا سازمان معروف، شخصیت یا نگرش هایی است که اکثر مردم فکر می کنند دارند","example":"attempts to improve the public image of the police","example_translation":"تلاش برای بهبود وجهه عمومی پلیس","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561767.mp3"},{"phrase":"public appearance","register":null,"definition_en":"a visit by a famous person in order to make a speech , advertise something etc","translation":"ملاقات یک فرد مشهور به منظور سخنرانی، تبلیغ چیزی و غیره","example":"She is paid £10,000 for the briefest of public appearances.","example_translation":"او 10000 پوند برای کوتاه ترین حضور در انظار عمومی دریافت می کند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561769.mp3"},{"phrase":"the public eye","register":null,"definition_en":"someone who is in the public eye is seen a lot on television , written about in newspapers etc","translation":"کسی که در معرض دید عموم است در تلویزیون زیاد دیده می شود، در روزنامه ها و غیره در مورد آن نوشته می شود","example":"It is a job that brings him constantly into the public eye.","example_translation":"این شغلی است که او را دائماً در معرض دید عموم قرار می دهد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561747.mp3"},{"phrase":"public property","register":null,"definition_en":"something that is provided for anyone to use, and is usually owned by the government","translation":"چیزی که برای استفاده هر کسی ارائه می شود و معمولاً متعلق به دولت است","example":"The army was called out to protect public property.","example_translation":"ارتش برای حفاظت از اموال عمومی فراخوانده شد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270054.mp3"},{"phrase":"public enemy number one","register":"informal","definition_en":"someone famous who has done something bad and who a lot of people do not like","translation":"شخص مشهوری که کار بدی انجام داده و بسیاری از مردم او را دوست ندارند","example":"His views made him public enemy number one in the eyes of the media.","example_translation":"دیدگاه های او او را به دشمن شماره یک در چشم رسانه ها تبدیل کرد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001678353.mp3"}]'::jsonb),
('0bf30e8b-190f-578a-a29a-929865734297','6030e7b1-859a-50c0-9411-2e27071cf13c',2,'noun','A2','S2','W2',null,'[{"phrase":"the public","register":null,"definition_en":"ordinary people who do not work for the government or have any special position in society","translation":"مردم عادی که برای دولت کار نمی کنند یا موقعیت خاصی در جامعه دارند","example":"The meeting will be open to the general public .","example_translation":"این جلسه برای عموم آزاد خواهد بود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270086.mp3"}]'::jsonb)
