('ad4e6713-d501-58dd-b4a2-3d4cad049e17','0229d10b-2bed-5646-a0e3-79fd6b8f25c7',1,null,null,'spoken & written','to quickly look at someone or something',null,null,'به سرعت به کسی یا چیزی نگاه کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The man glanced nervously at his watch.","translation":"مرد با عصبانیت به ساعتش نگاه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001297670.mp3"},{"sentence":"Wyatt glanced around the restaurant.","translation":"وایت نگاهی به اطراف رستوران انداخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001297671.mp3"},{"sentence":"Emily glanced over her shoulder.","translation":"امیلی نگاهی به شانه اش انداخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698058.mp3"}]'::jsonb,3),
('e2c3ecab-c715-5d31-a677-8219afbe0d61','0229d10b-2bed-5646-a0e3-79fd6b8f25c7',2,null,null,'spoken & written','to read something very quickly',null,null,'برای خواندن چیزی خیلی سریع','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Can you glance through these figures for me?","translation":"آیا می توانید به این ارقام برای من نگاهی بیندازید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001297675.mp3"},{"sentence":"I took a quick look at my watch.","translation":"نگاهی سریع به ساعتم انداختم.","audio_url":null}]'::jsonb,2),
('a02bf768-15f9-55c3-b8b7-9ce7c954b8d2','0071a940-38fc-52fc-8411-e8bc2dbb5449',1,null,null,'spoken & written','a quick look',null,null,'نگاه سریع، برق دید','{}'::text[],'{}'::text[],array['give something/somebody a glance He gave Imran a quick glance.','take a glance ( also have a glance British English ) She took a quick glance around the office.','cast/throw a glance (= look quickly ) She cast a shy glance toward Shelby.','shoot a glance (= look extremely quickly ) He shot a glance at Ellen, making sure she understood him.','steal a glance (= look quickly and secretly ) Alice stole a quick glance in the mirror to check her hair.','exchange glances (= look at each other quickly ) Mai exchanged glances with Tatsuya.','somebody’s glance falls on something (= someone looks at something ) Geoff’s glance fell on the broken vase.','a quick/brief glance I had little time for more than a quick glance around the house.','a cursory glance (= a very quick look without much attention to details ) I cast a cursory glance over the clothes.','a fleeting glance (= a very quick look ) Stephen exchanged a fleeting glance with his father.','a backwards glance He took a quick backwards glance at the house, and then continued walking.','a sidelong/sideways glance (= a way of looking by moving your eyes to the side ) Christina gave her husband a sidelong glance.','a casual glance (= without any serious interest or attention ) The bench would have been difficult to see by a casual glance.','a meaningful glance (= clearly showing what you think ) They exchanged meaningful glances.','a furtive glance (= a quick secret look ) Della gave Chris a furtive glance.','a nervous glance He shot a nervous glance at his wife.','a warning glance She cast a warning glance at Elena.']::text[],'[{"sentence":"He gave her a quick glance and smiled.","translation":"نگاهی سریع به او انداخت و لبخند زد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698065.mp3"},{"sentence":"She couldn’t resist a sidelong glance (= a look that is not direct ) at him.","translation":"او نتوانست در برابر یک نگاه جانبی (= نگاه غیر مستقیم) به او مقاومت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698073.mp3"},{"sentence":"The couple at the next table cast quick glances in our direction.","translation":"زن و شوهری که در میز کناری بودند نگاهی سریع به سمت ما انداختند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001298398.mp3"},{"sentence":"The brothers exchanged glances (= looked at each other quickly ) .","translation":"برادران با هم نگاه كردند (= به سرعت به هم نگاه كردند ) .","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698078.mp3"}]'::jsonb,4),
