('51c4081d-f24d-52ae-9009-b5c7d1710af0','59b7b6da-0715-5ef6-8d62-8df2ffbb126a',1,'earth','زمین','spoken & written','the surface of the Earth','[ uncountable ]',null,'زمین، خاک؛ زیر (ساختمان)؛ دشت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The leaves were slowly fluttering to the ground.","translation":"برگ ها به آرامی روی زمین بال می زدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785628.mp3"},{"sentence":"He lay on the ground and stared up at the sky.","translation":"روی زمین دراز کشید و به آسمان خیره شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001305179.mp3"},{"sentence":"The ground was frozen solid.","translation":"زمین جامد یخ زده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785629.mp3"},{"sentence":"At night, badgers feed above ground.","translation":"در شب، گورکن ها از بالای زمین تغذیه می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785632.mp3"},{"sentence":"These youngsters work 70 metres below ground level .","translation":"این جوانان 70 متر زیر سطح زمین کار می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785633.mp3"},{"sentence":"A raised platform stood two metres off the ground.","translation":"یک سکوی بلند دو متری از زمین ایستاده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020074.mp3"},{"sentence":"The air raids were followed by military action on the ground (= on land ) .","translation":"حملات هوایی با عملیات نظامی در زمین (= در خشکی) دنبال شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001305180.mp3"},{"sentence":"ground troops (= soldiers who fight on land )","translation":"نیروهای زمینی (= سربازانی که در خشکی می جنگند)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785642.mp3"},{"sentence":"Dig the ground over in the autumn.","translation":"در پاییز زمین را حفر کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785647.mp3"},{"sentence":"Plant the seeds 2 cm deep in the ground.","translation":"بذرها را به عمق 2 سانتی متر در زمین بکارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785648.mp3"},{"sentence":"The ground was dry, far too dry for growing corn.","translation":"زمین خشک بود و برای کشت ذرت خیلی خشک بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785649.mp3"}]'::jsonb,11),
('298519b6-d715-5d50-914b-5a644aec4739','59b7b6da-0715-5ef6-8d62-8df2ffbb126a',2,'area of land','مساحت زمین','spoken & written','an area of land without buildings , fences , woods etc','[ uncountable ]','playground ( 1 )','مساحت زمین بدون ساختمان، حصار، جنگل و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The landscape is a mixture of open ground and woodland.","translation":"منظره ترکیبی از زمین باز و جنگل است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001305215.mp3"},{"sentence":"They were standing on the waste ground (= land in a town that is not being used ) behind the car park.","translation":"آنها روی زمین باطله (= زمینی در شهری که استفاده نمی شود) پشت پارکینگ ایستاده بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001305216.mp3"},{"sentence":"fishing grounds","translation":"مناطق ماهیگیری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785668.mp3"},{"sentence":"These fields served as a hunting ground for the local people.","translation":"این مزارع به عنوان شکارگاه مردم محلی بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785671.mp3"},{"sentence":"The rivers are used as dumping grounds for industrial waste.","translation":"از این رودخانه ها به عنوان محل تخلیه زباله های صنعتی استفاده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785672.mp3"},{"sentence":"He is buried in sacred ground.","translation":"او در زمین مقدس دفن شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785676.mp3"},{"sentence":"We decided to take a stroll in the hotel grounds.","translation":"تصمیم گرفتیم در محوطه هتل قدم بزنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785685.mp3"}]'::jsonb,7),
