('9fad07f6-f0aa-5233-a209-8be22e1d1ce6','59b7b6da-0715-5ef6-8d62-8df2ffbb126a',5,'opinion','نظر','spoken & written','a general opinion or set of attitudes','[ uncountable ]',null,'یک نظر کلی یا مجموعه ای از نگرش ها','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Often parents and teenagers find they have little common ground (= they do not share the same attitudes etc ) .","translation":"اغلب والدین و نوجوانان متوجه می شوند که زمینه مشترک کمی دارند (= نگرش های یکسانی ندارند و غیره).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785728.mp3"},{"sentence":"Both parties are battling to occupy the centre ground .","translation":"هر دو طرف در حال مبارزه برای اشغال میدان مرکزی هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785736.mp3"},{"sentence":"Careful, Laura. You could be treading on dangerous ground (= expressing opinions etc that might offend someone ) .","translation":"مواظب باش لورا شما ممکن است روی زمین خطرناکی قدم بگذارید (= ابراز عقاید و غیره که ممکن است به کسی توهین کند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785740.mp3"},{"sentence":"Each side was unwilling to give ground (= change their opinion ) .","translation":"هر یک از طرفین حاضر به تسلیم شدن (= تغییر عقیده خود) نبودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001785745.mp3"}]'::jsonb,4),
