('9000944f-c35d-5af0-a96f-8014c3ad7340','8eeffbb3-a687-54d7-8305-f2d80f84201a',1,null,null,'spoken & written','almost not',null,null,'تقریباً نه، به‌سختی؛ هیچ‌وقت (تقریباً)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My parents divorced when I was six, and I hardly knew my father.","translation":"پدر و مادرم در شش سالگی طلاق گرفتند و من به سختی پدرم را می شناختم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001711871.mp3"},{"sentence":"The children were so excited they could hardly speak.","translation":"بچه ها آنقدر هیجان زده بودند که به سختی می توانستند صحبت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344611.mp3"},{"sentence":"I can hardly believe it.","translation":"من به سختی می توانم آن را باور کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344612.mp3"},{"sentence":"Hardly anyone (= almost no one ) writes to me these days.","translation":"این روزها کمتر کسی (= تقریباً هیچ کس) برای من نامه نمی نویسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344616.mp3"},{"sentence":"Dad ate hardly anything (= almost nothing ) .","translation":"پدر تقریباً چیزی نخورد (= تقریباً هیچ چیز).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001711881.mp3"},{"sentence":"There was hardly any (= very little ) traffic.","translation":"به سختی (= بسیار کم) ترافیک وجود داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001711886.mp3"},{"sentence":"She lives in Spain, so we hardly ever (= almost never ) see her.","translation":"او در اسپانیا زندگی می کند، بنابراین ما به ندرت (= تقریباً هرگز) او را نمی بینیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344624.mp3"},{"sentence":"Hardly a month goes by without another factory closing down.","translation":"به سختی یک ماه می گذرد که کارخانه دیگری تعطیل نشود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344628.mp3"}]'::jsonb,8),
('27f92ac1-d1f6-5c9c-8ab6-8ee2be9635f8','8eeffbb3-a687-54d7-8305-f2d80f84201a',2,null,null,'spoken & written','used to mean ‘not’, when you are suggesting that the person you are speaking to will agree with you',null,null,'زمانی به معنای "نه" بود، زمانی که به کسی که با او صحبت می کنید با شما موافق است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s hardly surprising that she won’t answer his calls after the way he’s treated her.","translation":"جای تعجب نیست که او پس از رفتاری که او با او داشته است به تماس های او پاسخ نمی دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344644.mp3"},{"sentence":"You can hardly blame Tom for not waiting.","translation":"به سختی می توانید تام را به خاطر صبر نکردن سرزنش کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001711898.mp3"},{"sentence":"My boss could hardly be described as handsome.","translation":"به سختی می توان رئیس من را خوش تیپ توصیف کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344655.mp3"},{"sentence":"This is hardly the place to discuss the matter.","translation":"اینجا به سختی جای بحث در این مورد نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344648.mp3"}]'::jsonb,4),
('ad451909-6d7a-59c7-abaf-3833d301df4a','8eeffbb3-a687-54d7-8305-f2d80f84201a',3,null,null,'spoken & written','used to say that something has only just happened',null,null,'قبلاً می گفت که چیزی تازه اتفاق افتاده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The building work has hardly begun.","translation":"کار ساختمان به سختی آغاز شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001711905.mp3"},{"sentence":"She had hardly sat down when the phone rang.","translation":"به سختی نشسته بود که تلفن زنگ خورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001344637.mp3"}]'::jsonb,2),
('aa75944e-8ea5-5792-97fb-23a3dac2fc00','6b0e1aad-85c8-581e-b855-e100a3b7e026',1,null,null,'spoken & written','the general condition of your body and how healthy you are',null,null,'سلامت، تندرستی؛ بهداشت (عمومی)','{}'::text[],'{}'::text[],array['good Physical exercise is essential to good health.','excellent At the age of 70, her health is excellent.','poor He wanted to join the army but his health was too poor.','ill health He retired early due to ill health.','failing health (= when someone is becoming more ill ) Despite failing health, he travelled to Australia to visit his son.','mental health Poverty affects children''s physical and mental health.','physical health Her physical health was generally good.','sexual health The programme aims to educate teenagers about sexual health.','general health (= the health of your whole body rather than a particular part ) A balanced diet will improve your general health.','human health Some chemicals pose a significant risk to human health.','damage your health There is no doubt that smoking can seriously damage your health.','endanger your health (= cause danger to your health ) Being overweight endangers your health.','improve (somebody''s) health Doing more exercise will improve your health.','somebody''s health improves Her health improved slowly after she came home from hospital.','somebody''s health deteriorates (= gets worse ) Her health deteriorated rapidly.','health care (= care from doctors, nurses etc ) Many Americans cannot afford even basic health care.','a health problem He missed a lot of time at work through health problems.','a health risk/hazard/threat (= something that could damage your health ) The report looked at the health risks linked to eating excess sugar.','health benefits the health benefits of doing yoga','health effects The study looked at the long-term health effects of drinking alcohol.','a health warning (= a warning printed on a product that could harm you ) the health warning on cigarette packets','be in good/poor health (= be healthy/unhealthy ) Her parents were elderly and in poor health.','be good/bad for your health Eating plenty of vegetables is good for your health.','somebody''s state of health Your choice of exercise must depend on your general state of health.','health and well-being The breakfast program improves the health and well-being of the children.']::text[],'[{"sentence":"I’m worried about my husband’s health.","translation":"من نگران سلامت شوهرم هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001966947.mp3"}]'::jsonb,1),
('c305fb4c-ae32-5c2b-b566-d9592f94182b','6b0e1aad-85c8-581e-b855-e100a3b7e026',2,null,null,'spoken & written','the work of providing medical services to keep people healthy',null,'public health','کار ارائه خدمات پزشکی برای حفظ سلامت مردم','{}'::text[],'{}'::text[],array['good Physical exercise is essential to good health.','excellent At the age of 70, her health is excellent.','poor He wanted to join the army but his health was too poor.','ill health He retired early due to ill health.','failing health (= when someone is becoming more ill ) Despite failing health, he travelled to Australia to visit his son.','mental health Poverty affects children''s physical and mental health.','physical health Her physical health was generally good.','sexual health The programme aims to educate teenagers about sexual health.','general health (= the health of your whole body rather than a particular part ) A balanced diet will improve your general health.','human health Some chemicals pose a significant risk to human health.','damage your health There is no doubt that smoking can seriously damage your health.','endanger your health (= cause danger to your health ) Being overweight endangers your health.','improve (somebody''s) health Doing more exercise will improve your health.','somebody''s health improves Her health improved slowly after she came home from hospital.','somebody''s health deteriorates (= gets worse ) Her health deteriorated rapidly.','health care (= care from doctors, nurses etc ) Many Americans cannot afford even basic health care.','a health problem He missed a lot of time at work through health problems.','a health risk/hazard/threat (= something that could damage your health ) The report looked at the health risks linked to eating excess sugar.','health benefits the health benefits of doing yoga','health effects The study looked at the long-term health effects of drinking alcohol.','a health warning (= a warning printed on a product that could harm you ) the health warning on cigarette packets','be in good/poor health (= be healthy/unhealthy ) Her parents were elderly and in poor health.','be good/bad for your health Eating plenty of vegetables is good for your health.','somebody''s state of health Your choice of exercise must depend on your general state of health.','health and well-being The breakfast program improves the health and well-being of the children.']::text[],'[{"sentence":"The government has promised to spend more on health and education.","translation":"دولت وعده داده است که برای سلامت و آموزش هزینه بیشتری خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001350702.mp3"},{"sentence":"health insurance","translation":"بیمه سلامت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001756764.mp3"},{"sentence":"nurses and other health workers","translation":"پرستاران و سایر کارکنان بهداشتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001756765.mp3"}]'::jsonb,3),
('81a6a0be-2475-53bf-bed3-049eaac12b42','6b0e1aad-85c8-581e-b855-e100a3b7e026',3,null,null,'spoken & written','when you have no illness or disease',null,null,'وقتی هیچ بیماری یا بیماری ندارید','{}'::text[],'{}'::text[],array['good Physical exercise is essential to good health.','excellent At the age of 70, her health is excellent.','poor He wanted to join the army but his health was too poor.','ill health He retired early due to ill health.','failing health (= when someone is becoming more ill ) Despite failing health, he travelled to Australia to visit his son.','mental health Poverty affects children''s physical and mental health.','physical health Her physical health was generally good.','sexual health The programme aims to educate teenagers about sexual health.','general health (= the health of your whole body rather than a particular part ) A balanced diet will improve your general health.','human health Some chemicals pose a significant risk to human health.','damage your health There is no doubt that smoking can seriously damage your health.','endanger your health (= cause danger to your health ) Being overweight endangers your health.','improve (somebody''s) health Doing more exercise will improve your health.','somebody''s health improves Her health improved slowly after she came home from hospital.','somebody''s health deteriorates (= gets worse ) Her health deteriorated rapidly.','health care (= care from doctors, nurses etc ) Many Americans cannot afford even basic health care.','a health problem He missed a lot of time at work through health problems.','a health risk/hazard/threat (= something that could damage your health ) The report looked at the health risks linked to eating excess sugar.','health benefits the health benefits of doing yoga','health effects The study looked at the long-term health effects of drinking alcohol.','a health warning (= a warning printed on a product that could harm you ) the health warning on cigarette packets','be in goo