('2058af05-5fd4-5d2f-adce-4ac5718d2235','679d42bf-3135-5904-9240-7626c127ecce',1,'place of god','جای خدا','spoken & written','the place where God is believed to live and where good people are believed to go when they die','[ singular ]',null,'بهشت، بهشت جاودانی؛ رضایت (آسمان)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He believed that he and his wife would one day be together again in heaven.","translation":"او معتقد بود که او و همسرش روزی دوباره در بهشت ​​با هم خواهند بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758124.mp3"}]'::jsonb,1),
