('561b702d-9857-5905-82e2-a6b58675c357','68c9584b-b9c2-5fff-99a6-7b3d147a8764',4,'given to somebody','به کسی داده شده','spoken & written','something such as a special title or medal given to someone to show how much people respect them for what they have achieved','[ countable ]',null,'چیزی مانند عنوان یا مدال ویژه ای که به کسی داده می شود تا نشان دهد که مردم چقدر به او برای آنچه به دست آورده اند احترام می گذارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Reverend Peters was nominated for the honour by colleagues at Walworth Methodist Church.","translation":"کشیش پیترز توسط همکارانش در کلیسای متدیست والورث برای این افتخار نامزد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745333.mp3"},{"sentence":"The medal is the highest honour the association can bestow (= give ) .","translation":"مدال بالاترین افتخاری است که انجمن می تواند اعطا کند (= بدهد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745337.mp3"}]'::jsonb,2),
('4bd3b722-b39d-55a2-8cd0-e5a2fa2f7984','68c9584b-b9c2-5fff-99a6-7b3d147a8764',5,'moral principles','اصول اخلاقی','spoken & written','strong moral beliefs and standards of behaviour that make people respect and trust you','[ uncountable ]',null,'باورهای اخلاقی قوی و معیارهای رفتاری که باعث می شود مردم به شما احترام بگذارند و به شما اعتماد کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My father was a man of honour and great integrity.","translation":"پدرم مردی شرافتمند و بزرگوار بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745344.mp3"},{"sentence":"Her actions were always guided by a deep sense of honour (= strong desire to do what is morally right ) .","translation":"اعمال او همیشه با احساس عمیق افتخار (= تمایل شدید برای انجام کاری که از نظر اخلاقی درست است) هدایت می شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745348.mp3"},{"sentence":"It had become a point of honour not to tell him about Lori.","translation":"نگفتن لری به او تبدیل به افتخار شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001358558.mp3"}]'::jsonb,3),
