('4b02bf42-da52-5e42-87c4-f209859130cb','fcfde7f2-99e5-59a9-865e-055c8959e9e3',2,null,null,'spoken & written','ill or weak as a result of not having enough to eat for a long time',null,null,'بیمار یا ضعیف به دلیل نداشتن غذای کافی برای مدت طولانی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We can’t justify wasting food when half the world is hungry.","translation":"وقتی نیمی از جهان گرسنه هستند نمی توانیم هدر دادن غذا را توجیه کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001365743.mp3"}]'::jsonb,1),
