('73ccb5ac-6561-5465-a3c8-2541017469ef','ed2295d3-0954-55be-8d87-47e91e1a65be',1,null,null,'spoken & written','to say firmly and often that something is true , especially when other people think it may not be true',null,null,'پافشاری کردن، اصرار داشتن؛ اصرار (بر حقیقت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Mike insisted that he was right.","translation":"مایک اصرار داشت که حق با اوست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001415407.mp3"},{"sentence":"His friends insisted he had no connection with drugs.","translation":"دوستانش اصرار داشتند که او هیچ ارتباطی با مواد مخدر نداشته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718897.mp3"},{"sentence":"She kept insisting on her innocence.","translation":"او همچنان بر بی گناهی خود پافشاری می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001415410.mp3"}]'::jsonb,3),
('b0c8063f-b104-5a8d-8282-30bf9fe05fd9','ed2295d3-0954-55be-8d87-47e91e1a65be',2,null,null,'spoken & written','to demand that something should happen',null,null,'تقاضا کنیم که اتفاقی بیفتد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Stay for supper – I insist !","translation":"برای شام بمان - اصرار دارم!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001415417.mp3"},{"sentence":"They insisted that everyone should come to the party.","translation":"آنها اصرار داشتند که همه به مهمانی بیایند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001415420.mp3"},{"sentence":"He insisted I should take a taxi.","translation":"او اصرار کرد که باید سوار تاکسی شوم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718900.mp3"},{"sentence":"We insist on the highest standards of cleanliness in the hotel.","translation":"ما بر بالاترین استانداردهای نظافت در هتل اصرار داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718901.mp3"},{"sentence":"He insisted upon checking everything himself.","translation":"او اصرار داشت که همه چیز را خودش بررسی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001718904.mp3"}]'::jsonb,5),
