('50f6aa92-3fe8-59dd-bbcf-19322741cf71','6a989498-4001-5117-8248-a7959f0dcce0',1,null,null,'spoken & written','to have something in your mind as a plan or purpose',null,null,'در نظر داشتن، قصد کردن؛ معنا دادن (برای)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I intend to spend the night there.","translation":"من قصد دارم شب را آنجا بگذرانم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721327.mp3"},{"sentence":"I didn’t intend her to see the painting until it was finished.","translation":"من قصد نداشتم او نقاشی را تا زمانی که تمام نشده ببیند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001418564.mp3"},{"sentence":"I never intended things to turn out the way they did.","translation":"من هرگز قصد نداشتم همه چیز آنطور پیش برود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001418565.mp3"},{"sentence":"It is intended that these meetings will become a regular event.","translation":"قرار است این جلسات به یک رویداد عادی تبدیل شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721332.mp3"},{"sentence":"We intend looking at the situation again.","translation":"ما قصد داریم دوباره به وضعیت نگاه کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721337.mp3"},{"sentence":"I fully intend (= definitely intend ) to return home next year.","translation":"من کاملاً قصد دارم (= قطعاً قصد دارم) سال آینده به خانه برگردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001418572.mp3"},{"sentence":"I plan to spend the night there.","translation":"قصد دارم شب را آنجا بگذرانم.","audio_url":null},{"sentence":"I didn’t plan on things taking so long. OR I didn’t plan for things to take so long.","translation":"من برای چیزهایی که اینقدر طول بکشد برنامه ریزی نکردم. یا برنامه ریزی نکرده بودم که همه چیز اینقدر طول بکشد.","audio_url":null}]'::jsonb,8),
