('b1d56084-1801-5da8-bdff-2b7242a01327','fe163cee-074c-5166-a274-bd9fb9223961',1,null,null,'spoken & written','to buy shares , property , or goods because you hope that the value will increase and you can make a profit','[ intransitive, transitive ]',null,'سرمایه‌گذاری کردن؛ در بازار گذاشتن (سهام)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’ve got a few thousand dollars I’m looking to invest.","translation":"من چند هزار دلار دارم که به دنبال سرمایه گذاری هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724271.mp3"},{"sentence":"Oliver made a fortune by investing in antique furniture.","translation":"الیور با سرمایه گذاری در مبلمان عتیقه به ثروت زیادی دست یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724274.mp3"},{"sentence":"Williams invested a large sum of money in Swiss stocks.","translation":"ویلیامز مقدار زیادی پول در سهام سوئیس سرمایه گذاری کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724275.mp3"},{"sentence":"He had invested heavily (= invested a lot of money ) in the bond market.","translation":"او در بازار اوراق قرضه بسیار (= پول زیادی سرمایه گذاری کرده بود) سرمایه گذاری کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001425173.mp3"}]'::jsonb,4),
('b841814d-b3a4-5075-bfd6-4b4cacc5c082','fe163cee-074c-5166-a274-bd9fb9223961',2,null,null,'spoken & written','if a government , business , or organization invests in something, they spend a large amount of money to improve it or help it succeed','[ intransitive, transitive ]',null,'اگر یک دولت، کسب و کار یا سازمانی در چیزی سرمایه گذاری کند، مقدار زیادی پول برای بهبود آن یا کمک به موفقیت آن خرج می کند.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The city has invested millions of dollars in the museum.","translation":"این شهر میلیون ها دلار در این موزه سرمایه گذاری کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724286.mp3"},{"sentence":"The factory plans to invest in new computers.","translation":"این کارخانه قصد دارد روی کامپیوترهای جدید سرمایه گذاری کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724287.mp3"},{"sentence":"He put money into his brother’s business.","translation":"او در تجارت برادرش پول گذاشت.","audio_url":null},{"sentence":"The government put in millions of pounds.","translation":"دولت میلیون ها پوند سرمایه گذاشت.","audio_url":null}]'::jsonb,4),
('09237c88-1380-5378-9f13-7cf08aa9a533','fe163cee-074c-5166-a274-bd9fb9223961',3,null,null,'spoken & written','to use a lot of time, effort etc or spend money in order to make something succeed','[ transitive ]',null,'استفاده از زمان، تلاش و غیره یا صرف هزینه برای موفقیت در کاری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was very difficult to leave a home we had invested so much in.","translation":"ترک خانه ای که در آن سرمایه گذاری زیادی کرده بودیم بسیار سخت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724290.mp3"}]'::jsonb,1),
('e2c36474-62ff-57c5-935d-f4803cb12d74','aed2c539-0419-5dac-8f85-747ee1800598',1,null,null,'spoken & written','to ask someone to come to a party , wedding , meal etc',null,null,'دعوت کردن؛ درخواست (پاسخ)؛ جلب کردن (نظر)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Who should we invite to the party?","translation":"چه کسی را به مهمانی دعوت کنیم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001427470.mp3"},{"sentence":"Gail invited me to stay with her while her husband was out of town.","translation":"گیل از من دعوت کرد تا زمانی که شوهرش خارج از شهر بود پیش او بمانم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724435.mp3"},{"sentence":"Why don’t you invite her for a drink at the club one evening?","translation":"چرا یک شب او را برای نوشیدنی در باشگاه دعوت نمی کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001427476.mp3"},{"sentence":"I’m afraid I wasn’t invited.","translation":"میترسم دعوت نشده باشم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001427479.mp3"},{"sentence":"Did they invite you to the wedding?","translation":"آیا شما را به عروسی دعوت کردند؟","audio_url":null},{"sentence":"She invited me to her house.","translation":"او مرا به خانه اش دعوت کرد.","audio_url":null},{"sentence":"He invited us for brunch.","translation":"او ما را برای ناهار دعوت کرد.","audio_url":null},{"sentence":"I’ll invite them for the weekend.","translation":"من آنها را برای آخر هفته دعوت خواهم کرد.","audio_url":null}]'::jsonb,8),
