('a16f609c-02c5-5b41-9db9-94f0875476cb','0007f376-7154-5636-9f86-b3ec21126e97',1,'work','کار کردن','spoken & written','work, especially physical work','[ uncountable ]','hard labour','کار (بدنی)؛ کارگران (طبقه)؛ زایمان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The garage charges £30 an hour for labour.","translation":"گاراژ برای کار ساعتی 30 پوند دریافت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001448276.mp3"},{"sentence":"Many women do hard manual labour (= work with their hands ) .","translation":"بسیاری از زنان کارهای سخت یدی (= کار با دستان خود) انجام می دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001448280.mp3"},{"sentence":"Workers withdrew their labour (= protested by stopping work ) for twenty-four hours.","translation":"کارگران به مدت بیست و چهار ساعت کار خود را پس گرفتند (= با توقف کار اعتراض کردند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001448284.mp3"}]'::jsonb,3),
('aef9daad-d7e1-51e2-9cf1-653879a61344','0007f376-7154-5636-9f86-b3ec21126e97',2,'workers','کارگران','spoken & written','all the people who work for a company or in a country','[ uncountable ]',null,'همه افرادی که برای یک شرکت یا در یک کشور کار می کنند','{}'::text[],'{}'::text[],array['skilled/unskilled labour Employers want to keep skilled labour because of the cost of training.','cheap labour (= workers who have low wages ) Women and children were used as cheap labour.','casual labour (= workers who do jobs that are not permanent ) The industry makes use of a large supply of casual labour.','child labour The shoe company was accused of using child labour in its factory.','slave labour Cotton was grown using slave labor.','the labour force (= all the people who work in a country or for a company ) We need an educated labour force.','the labour supply (= all the people available to work ) What was the effect of the war on the labour supply?','the labour market (= the people looking for work and the jobs available ) the percentage of women in the labour market','a labour shortage Immigrants came into the country to fill the labour shortage.','labour costs There was pressure to keep down labour costs.']::text[],'[{"sentence":"a shortage of skilled labor","translation":"کمبود نیروی کار ماهر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001448297.mp3"},{"sentence":"We need to reduce our labour costs.","translation":"ما باید هزینه های نیروی کار خود را کاهش دهیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001735526.mp3"}]'::jsonb,2),
('3a9b1c48-8a87-52de-8b29-fe9692e408ad','0007f376-7154-5636-9f86-b3ec21126e97',3,'baby','عزیزم','spoken & written','the process of giving birth to a baby','[ singular, uncountable ]',null,'روند تولد نوزاد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Meg was in labour for ten hours.","translation":"مگ ده ساعت در حال زایمان بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001735535.mp3"},{"sentence":"Diane went into labour at 2 o''clock.","translation":"دایان ساعت 2 زایمان کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001448318.mp3"},{"sentence":"The labour pains were unbearable.","translation":"درد زایمان غیر قابل تحمل بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001735541.mp3"}]'::jsonb,3),
