('72110558-e495-5537-837b-2e92f6bea365','9c802826-6714-54e5-a087-515730208845',1,'size','اندازه','spoken & written','the measurement of how long something is from one end to the other','[ countable, uncountable ]',null,'طول، درازا؛ طول (مدت)؛ بند (متن)','{}'::text[],'{}'::text[],array['measure the length of something The children measured the length of their shadows at three different times of day.','have a length of 1 metre/2 feet etc These leaves have a length of about 7 cm.','grow to/reach a length of 2 metres/8 feet etc A blue whale can reach a length of 100 feet.','run the length of something (= exist along the whole length of something ) A long corridor ran the length of the building.','the total length The total length of the completed railway line will be almost 650 kilometres.','an average length These worms grow to an average length of about 1 metre.','the whole/full/entire length of something The camera looks down the full length of the street.','medium length All the girls had short or medium length hair.','equal/unequal length She drew two lines of equal length.','a maximum/minimum length This species of fish can reach a maximum length of 12 inches.']::text[],'[{"sentence":"We measured the length and width of the living room.","translation":"طول و عرض اتاق نشیمن را اندازه گرفتیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742412.mp3"},{"sentence":"Some fish can grow to a length of four feet.","translation":"برخی از ماهی ها می توانند تا چهار فوت رشد کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742415.mp3"},{"sentence":"The hotel pool is 15 metres in length.","translation":"طول استخر هتل 15 متر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453166.mp3"},{"sentence":"You’ll need several pieces of string of different lengths.","translation":"شما به چند تکه رشته با طول های مختلف نیاز دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453167.mp3"}]'::jsonb,4),
('ad6bbbcf-8484-5e18-a818-96494c9afec3','9c802826-6714-54e5-a087-515730208845',2,'time','زمان','spoken & written','the amount of time that you spend doing something or that something continues','[ countable, uncountable ]',null,'مقدار زمانی که برای انجام کاری صرف می کنید یا اینکه چیزی ادامه دارد','{}'::text[],'{}'::text[],array['measure the length of something The children measured the length of their shadows at three different times of day.','have a length of 1 metre/2 feet etc These leaves have a length of about 7 cm.','grow to/reach a length of 2 metres/8 feet etc A blue whale can reach a length of 100 feet.','run the length of something (= exist along the whole length of something ) A long corridor ran the length of the building.','the total length The total length of the completed railway line will be almost 650 kilometres.','an average length These worms grow to an average length of about 1 metre.','the whole/full/entire length of something The camera looks down the full length of the street.','medium length All the girls had short or medium length hair.','equal/unequal length She drew two lines of equal length.','a maximum/minimum length This species of fish can reach a maximum length of 12 inches.']::text[],'[{"sentence":"Your pension will depend on your length of employment.","translation":"بازنشستگی شما به مدت زمان کار شما بستگی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742418.mp3"},{"sentence":"What’s the average length of stay in hospital?","translation":"میانگین مدت اقامت در بیمارستان چقدر است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742419.mp3"},{"sentence":"He wasn’t left alone for any length of time.","translation":"او برای مدت زیادی تنها نگذاشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453183.mp3"}]'::jsonb,3),
