('1baa158e-6f5c-54fb-b254-d2ad3005ff97','e7223f66-bda3-59ee-aab2-761b6014c23a',1,'learning a skill','یادگیری یک مهارت','spoken & written','a period of time in which someone is taught a particular skill , for example how to play a musical instrument or drive a car',null,null,'درس، آموزشگاه (مهارت)؛ پند، عبرت؛ کلاس','{}'::text[],'{}'::text[],array['take lessons He started taking piano lessons at age four.','have lessons I have swimming lessons on Friday.','go to a lesson ( also attend a lesson formal ) I have to go to my French lesson now.','give lessons (= teach lessons ) She made a living giving private lessons in English.','prepare a lesson The teachers spend a long time preparing their lessons.','a history/physics/maths etc lesson I''ve got a history lesson this afternoon.','a driving/swimming etc lesson Dad said he''d pay for driving lessons as my birthday present.','a piano/guitar etc lesson I''d just started classical guitar lessons.','a private lesson (= a lesson specially for one person rather than for a class ) He gave private lessons in mathematics at the weekends.']::text[],'[{"sentence":"piano lessons","translation":"آموزش پیانو","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453800.mp3"},{"sentence":"She’s started taking driving lessons.","translation":"او شروع به درس رانندگی کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453803.mp3"},{"sentence":"lessons in First Aid","translation":"درس کمک های اولیه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453806.mp3"},{"sentence":"lessons in road safety","translation":"درس ایمنی راه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002092049.mp3"}]'::jsonb,4),
('298dce08-dc80-5561-b38f-b39cb455c01b','e7223f66-bda3-59ee-aab2-761b6014c23a',2,'in school','در مدرسه','spoken & written','a period of time in which school students are taught a particular subject',null,null,'دوره زمانی که در آن به دانش آموزان مدرسه موضوع خاصی آموزش داده می شود','{}'::text[],'{}'::text[],array['take lessons He started taking piano lessons at age four.','have lessons I have swimming lessons on Friday.','go to a lesson ( also attend a lesson formal ) I have to go to my French lesson now.','give lessons (= teach lessons ) She made a living giving private lessons in English.','prepare a lesson The teachers spend a long time preparing their lessons.','a history/physics/maths etc lesson I''ve got a history lesson this afternoon.','a driving/swimming etc lesson Dad said he''d pay for driving lessons as my birthday present.','a piano/guitar etc lesson I''d just started classical guitar lessons.','a private lesson (= a lesson specially for one person rather than for a class ) He gave private lessons in mathematics at the weekends.']::text[],'[{"sentence":"Lessons start at 9 o''clock.","translation":"شروع درس از ساعت 9","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453818.mp3"},{"sentence":"I’ve got a double maths lesson next.","translation":"من یک درس ریاضی دوتایی دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742557.mp3"},{"sentence":"Andrew gives private lessons in Spanish.","translation":"اندرو دروس خصوصی به زبان اسپانیایی می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001453822.mp3"}]'::jsonb,3),
('259983f4-bc82-5855-9eb7-d48d57972fe4','e7223f66-bda3-59ee-aab2-761b6014c23a',3,'experience','تجربه','spoken & written','something that provides experience or information that you can learn from and use',null,null,'چیزی که تجربه یا اطلاعاتی را ارائه می دهد که می توانید از آن بیاموزید و از آن استفاده کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There were important lessons to be learned from these discoveries.","translation":"از این اکتشافات درس های مهمی می شد آموخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742567.mp3"},{"sentence":"The government has failed to learn the lessons of history .","translation":"دولت نتوانسته از تاریخ درس بگیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002092050.mp3"},{"sentence":"The men’s courage and faith is a lesson to us all.","translation":"شجاعت و ایمان مردان برای همه ما درس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742570.mp3"},{"sentence":"Now let that be a lesson to you all (= be careful to avoid having the same bad experience again ) .","translation":"حالا بگذارید این درس برای همه شما باشد (= مراقب باشید که دوباره همان تجربه بد را نداشته باشید).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742571.mp3"},{"sentence":"Her fate should be a salutary lesson (= one that teaches or warns you about something ) .","translation":"سرنوشت او باید یک درس مفید باشد (= چیزی که به شما یاد می دهد یا در مورد چیزی هشدار می دهد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742576.mp3"}]'::jsonb,5),
