('f5e1b422-c08a-5e6d-aa85-e746b89ab675','4c22372f-ed79-5cf8-8486-c498aa3e69f7',1,null,null,'spoken & written','to write, draw , paint etc letters or words on something','[ transitive ]',null,'نوشتن، کشیدن، نقاشی کردن حروف یا کلمات و غیره روی چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The card was neatly lettered P. A. DUFFY.","translation":"کارت با حروف منظم P. A. DUFFY نوشته شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00543.mp3"},{"sentence":"Several pages are lettered in gold.","translation":"چندین صفحه با حروف طلایی نوشته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001742651.mp3"}]'::jsonb,2),
