('a33c0894-ab6c-5b3e-9488-13f2b6eb7a74','a110b3fc-a39f-5a56-b670-79ca4cc85628',1,null,null,'spoken & written','used to mention the main part or cause of something, the main reason for something etc',null,null,'عمده‌تأ، به‌طور عمده؛ عمدتاً',array['primarily']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her illness was caused mainly by stress.","translation":"بیماری او عمدتاً ناشی از استرس بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173533.mp3"},{"sentence":"The workforce is mainly made up of women.","translation":"نیروی کار عمدتاً از زنان تشکیل شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000173534.mp3"},{"sentence":"I don’t go out much, mainly because I have to look after the kids.","translation":"من زیاد بیرون نمی روم، عمدتاً به این دلیل که باید از بچه ها مراقبت کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001534070.mp3"},{"sentence":"Increased sales during the summer were mainly due to tourism.","translation":"افزایش فروش در طول تابستان عمدتا به دلیل گردشگری بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001534074.mp3"},{"sentence":"We talked about various things – work, mainly.","translation":"ما در مورد چیزهای مختلف صحبت کردیم - عمدتاً کار.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752759.mp3"},{"sentence":"They play mainly on Sundays.","translation":"آنها عمدتا یکشنبه ها بازی می کنند.","audio_url":null},{"sentence":"People go there mainly because of the beautiful beaches.","translation":"مردم عمدتا به دلیل سواحل زیبا به آنجا می روند.","audio_url":null},{"sentence":"I read novels, mainly.","translation":"من عمدتاً رمان می خوانم.","audio_url":null},{"sentence":"The disease is caused chiefly by poor sanitation.","translation":"این بیماری عمدتاً به دلیل بهداشت نامناسب ایجاد می شود.","audio_url":null}]'::jsonb,9),
('39929d5d-87a1-5d43-995f-898c426d0948','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',1,'business','کسب و کار','spoken & written','to direct or control a business or department and the people, equipment , and money involved in it','[ transitive ]',null,'مدیریت کردن، اداره کردن (بنگاه)؛ مهار کردن (شب)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was asked to manage a new department.","translation":"از او خواسته شد تا یک بخش جدید را مدیریت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181526.mp3"},{"sentence":"Managing a football team is harder than you think.","translation":"مدیریت یک تیم فوتبال سخت تر از آن چیزی است که فکر می کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181527.mp3"},{"sentence":"The company had been very badly managed.","translation":"شرکت بسیار بد مدیریت شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181528.mp3"},{"sentence":"a brewery which has been owned and managed by the same family for over 100 years","translation":"یک کارخانه آبجوسازی که بیش از 100 سال است که توسط یک خانواده اداره می شود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759047.mp3"}]'::jsonb,4),
('ccef7c7d-8ebd-58a4-9447-04b93f514217','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',2,'do something difficult','انجام یک کار دشوار','spoken & written','to succeed in doing something difficult , especially after trying very hard','[ intransitive, transitive ]',null,'برای موفقیت در انجام کاری سخت، به ویژه پس از تلاش بسیار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I finally managed to push the huge animal away.","translation":"بالاخره موفق شدم حیوان بزرگ را هل دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181469.mp3"},{"sentence":"How do you manage to stay so slim?","translation":"چگونه می توانید اینقدر لاغر بمانید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181470.mp3"},{"sentence":"We somehow managed to persuade him.","translation":"ما به نوعی توانستیم او را متقاعد کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817024.mp3"},{"sentence":"Juventus managed two goals in the last ten minutes.","translation":"یوونتوس در ده دقیقه آخر دو گل به ثمر رساند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181474.mp3"},{"sentence":"I don’t know how I’ll manage it , but I’ll be there.","translation":"من نمی دانم چگونه آن را مدیریت کنم، اما من آنجا خواهم بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181477.mp3"},{"sentence":"At a time of depression, Roosevelt succeeded in restoring hope.","translation":"روزولت در زمان افسردگی موفق شد امید را بازگرداند.","audio_url":null}]'::jsonb,6),
('ac765c84-a466-5d7b-a72d-c96bd1c7e780','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',3,'deal with problems','با مشکلات برخورد کنید','spoken & written','to succeed in dealing with problems, living in a difficult situation etc','[ intransitive ]',null,'برای موفقیت در رویارویی با مشکلات، زندگی در شرایط سخت و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I don’t know how she manages with seven children.","translation":"نمی‌دانم او با هفت فرزند چگونه رفتار می‌کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181484.mp3"},{"sentence":"We didn’t have the proper equipment, but we managed somehow.","translation":"ما تجهیزات مناسبی نداشتیم، اما به نوعی توانستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759054.mp3"},{"sentence":"How do you manage without a washing machine?","translation":"چگونه بدون ماشین لباسشویی مدیریت می کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181487.mp3"},{"sentence":"I can’t afford to get you a new coat – you’ll have to manage with the one you’ve got.","translation":"من نمی توانم برای شما یک کت جدید تهیه کنم - شما باید با کتی که دارید مدیریت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001533841.mp3"}]'::jsonb,4),
('034a6eb2-9a23-5f64-bb9c-3954869387d7','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',4,'time/money etc','زمان / پول و غیره','spoken & written','to use your time, money etc sensibly, without wasting it','[ transitive ]',null,'برای استفاده معقول از زمان، پول و غیره، بدون اتلاف آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Paying a little each month can help you manage your money.","translation":"پرداخت اندکی در هر ماه می تواند به شما در مدیریت پول کمک کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181534.mp3"},{"sentence":"You need to learn to manage your time more effectively.","translation":"شما باید یاد بگیرید که زمان خود را به طور موثرتری مدیریت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001533843.mp3"},{"sentence":"Consultants can help academic institutions to manage their resources more efficiently.","translation":"مشاوران می توانند به مؤسسات دانشگاهی کمک کنند تا منابع خود را به نحو احسن مدیریت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759055.mp3"}]'::jsonb,3),
('3aaee1f9-7346-5780-9aa9-005e8e9440c1','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',5,'live without much money','بدون پول زیاد زندگی کنید','spoken & written','to succeed in buying the things that you need in order to live even though you do not have very much money','[ intransitive ]',null,'برای موفقیت در خرید چیزهایی که برای زندگی نیاز دارید، حتی اگر پول زیادی ندارید',array['get by']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I honestly don’t know how we’ll manage now Keith’s lost his job.","translation":"راستش نمی‌دانم حالا که کیت کارش را از دست داده است، چگونه می‌توانیم مدیریت کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181497.mp3"},{"sentence":"It’ll be tight, but I guess I’ll just about manage.","translation":"سخت خواهد بود، اما حدس می‌زنم که تقریباً مدیریت خواهم کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759056.mp3"},{"sentence":"People like Jim have to manage on as little as $75 a week.","translation":"افرادی مانند جیم باید حداقل ۷۵ دلار در هفته را مدیریت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181500.mp3"}]'::jsonb,3),
('ce92310a-122a-54da-aff2-a4cc0eaffba0','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',6,'not need help','نیازی به کمک ندارد','spoken','to be able to do something or carry something without help','[ intransitive, transitive ]',null,'توانایی انجام کاری یا حمل چیزی بدون کمک','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Can you manage all right, Mum?","translation":"آیا می توانی همه چیز را خوب مدیریت کنی، مامان؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181507.mp3"},{"sentence":"You’ll never manage that suitcase; let me take it.","translation":"شما هرگز آن چمدان را مدیریت نخواهید کرد. بگذار آن را بگیرم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181510.mp3"},{"sentence":"Thank you, but I think I can manage perfectly well on my own.","translation":"متشکرم، اما فکر می کنم به تنهایی می توانم به خوبی مدیریت کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759057.mp3"}]'::jsonb,3),
('6cee8126-3c8b-5022-b0fb-d8333742bb8c','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',7,'keep tidy','مرتب نگه دارید','spoken & written','to succeed in keeping something neat and tidy','[ transitive ]',null,'موفق شدن در نگه داشتن چیزی مرتب و مرتب','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He’ll never manage such a big garden on his own.","translation":"او هرگز چنین باغ بزرگی را به تنهایی مدیریت نخواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181540.mp3"}]'::jsonb,1),
('5cae0ab9-3650-599b-9f4a-3c90d99ed4d0','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',8,'control','کنترل کنید','spoken & written','to control the behaviour of a person or animal , so that they do what you want','[ transitive ]',null,'برای کنترل رفتار یک فرد یا حیوان، به طوری که آنها آنچه را که شما می خواهید انجام دهند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s hard to manage your children and do the shopping.","translation":"مدیریت فرزندان و خرید کردن سخت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181547.mp3"},{"sentence":"The horse was huge and vicious. Giles was the only one who could manage her.","translation":"اسب بزرگ و شرور بود. گیلز تنها کسی بود که توانست او را مدیریت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001533844.mp3"}]'::jsonb,2),
('f1ddee8c-cd4d-547b-8014-374296ca8e90','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',9,'be strong enough','به اندازه کافی قوی باشید','spoken & written','to be able to do something because you are strong enough or healthy enough','[ transitive ]',null,'بتوانید کاری را انجام دهید زیرا به اندازه کافی قوی هستید یا به اندازه کافی سالم هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He tried to walk, but managed only a few shaky steps.","translation":"سعی کرد راه برود، اما تنها چند قدم لرزان را پشت سر گذاشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181553.mp3"}]'::jsonb,1),
('4f1a835b-5c16-5ea5-9e65-47f6e976a9aa','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',10,'eat/drink','خوردن/نوشیدن','spoken & written','to be able to eat or drink something','[ transitive ]',null,'توانایی خوردن یا نوشیدن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Could you manage another drink?","translation":"آیا می توانید نوشیدنی دیگری را مدیریت کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181561.mp3"}]'::jsonb,1),
('ea297902-93a4-5a18-88cb-3855f958c710','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',11,'cause problems','مشکلاتی ایجاد کند','spoken & written','to do something that causes problems – used humorously','[ transitive ]',null,'انجام کاری که باعث ایجاد مشکل می شود - به صورت طنز استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Andrews has managed to get himself sacked.","translation":"اندروز توانسته خود را اخراج کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181519.mp3"},{"sentence":"I don’t know how I managed to arrive so late.","translation":"نمی دانم چطور توانستم اینقدر دیر رسیدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181520.mp3"}]'::jsonb,2),
('6ed30e9a-87bb-5581-a52c-3e018886d2b5','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',12,null,null,'spoken & written',null,null,'manage a few words/a smile etc','مدیریت کردن، اداره کردن (بنگاه)؛ مهار کردن (شب)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0a8e6ba1-312a-510f-bec1-ac7c3c3620e1','dc3c6daf-d5a7-5626-8cb6-204f1c1f1923',13,'have time for','برای','spoken & written','to be able to meet someone or do something, even though you are busy','[ transitive ]',null,'بتوانید با کسی ملاقات کنید یا کاری انجام دهید، حتی اگر مشغول هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Can you manage dinner tonight?","translation":"آیا می توانید شام امشب را مدیریت کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000181572.mp3"},{"sentence":"‘Is there any chance you could work late?’ ‘I think I could manage an hour.’","translation":"آیا شانسی وجود دارد که بتوانید تا دیر وقت کار کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001533851.mp3"}]'::jsonb,2),
('3bd0231b-9b17-5fbc-a74a-1e2675c74e2b','f482122e-dfa9-5a0d-86b5-ddb2cbe12054',1,null,null,'formal','the way in which something is done or happens','[ singular ]',null,'شیوه، اسلوب؛ رفتار (ادب)؛ صورت (نوع)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It seemed rather an odd manner of deciding things.","translation":"تصمیم گیری نسبتاً عجیب و غریب به نظر می رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000183438.mp3"},{"sentence":"He felt some guilt over the manner of her death.","translation":"او در مورد نحوه مرگ او احساس گناه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001554040.mp3"},{"sentence":"I had hoped you would behave in a more responsible manner.","translation":"امیدوارم رفتار مسئولانه تری داشته باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751940.mp3"},{"sentence":"The issue will be resolved in a manner that is fair to both sides.","translation":"موضوع به گونه ای حل خواهد شد که برای هر دو طرف منصفانه باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000183441.mp3"},{"sentence":"criticism of the manner in which the bishop was appointed","translation":"انتقاد از نحوه انتصاب اسقف","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817249.mp3"},{"sentence":"The matter should be submitted to the accounts committee in the usual manner.","translation":"موضوع باید به روش معمول به کمیته محاسبات ارائه شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751943.mp3"},{"sentence":"They behaved in a very reasonable way .","translation":"آنها رفتار بسیار معقولی داشتند.","audio_url":null},{"sentence":"They behaved very reasonably .","translation":"خیلی منطقی رفتار کردند.","audio_url":null}]'::jsonb,8),
('5b21cb0c-bc73-5118-ba80-ea0134826b1e','f482122e-dfa9-5a0d-86b5-ddb2cbe12054',2,null,null,'spoken & written','the way in which someone behaves towards or talks to other people','[ singular ]',null,'روشی که در آن شخص با افراد دیگر رفتار می کند یا با آنها صحبت می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She has a calm relaxed manner.","translation":"او حالت آرام آرامی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000183448.mp3"},{"sentence":"Something in Beth’s manner towards him had changed.","translation":"چیزی در رفتار بث نسبت به او تغییر کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001554041.mp3"},{"sentence":"Sophie resented his high-handed manner.","translation":"سوفی از رفتار بالا دست او ناراحت شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817257.mp3"}]'::jsonb,3),
('a3d798ee-713f-5412-a21b-134d558eff21','f482122e-dfa9-5a0d-86b5-ddb2cbe12054',3,null,null,'spoken & written',null,null,'manners','شیوه، اسلوب؛ رفتار (ادب)؛ صورت (نوع)','{}'::text[],'{}'::text[],array['have good/bad manners All their children have such good manners.','mind your manners ( also remember your manners British English ) (= used for telling a child to behave politely ) I frowned at him and told him to mind his manners.','have no manners (= regularly not behave politely ) He has no manners and he eats like a pig.','forget your manners (= behave in an impolite way ) Oh, I’m forgetting my manners. Let me introduce you to Suzanne.','teach somebody manners (= often used when criticizing someone’s impolite behaviour ) Those girls need to be taught some manners!','it’s good/bad manners to do something It’s bad manners to chew with your mouth open.','where are your manners? British English (= used for telling a child to stop behaving impolitely ) Jamie! Where are your manners?','good manners Good manners could not prevent her from asking the question.','bad manners She apologized for her son’s bad manners.','excellent/beautiful manners (= very good manners ) Her children have excellent manners.','perfect/impeccable manners Suddenly, his perfect manners were gone.','nice manners (= good manners ) She has such nice manners.','table manners (= the polite way of eating at a table ) My parents expected us to have good table manners.']::text[],'[]'::jsonb,0),
