('a3ba3267-fec3-5f4f-b329-e03bf830da60','c67640a2-c3a4-5e40-b019-f1ff26d4e168',2,null,null,'spoken & written','to manage to control a strong emotion',null,null,'برای کنترل یک احساس قوی',array['overcome']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He had learned to master his fear of heights.","translation":"او یاد گرفته بود که بر ترس از ارتفاع مسلط شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752378.mp3"}]'::jsonb,1),
