('d0a0103d-5972-5ab3-9152-881f1de9f5e2','729d0c27-7fb5-5e87-9439-a8e487d5c9f7',1,null,null,'spoken & written','to be important, especially to be important to you, or to have an effect on what happens','[ intransitive not in progressive ]',null,'اهمیت داشتن؛ تأثیر داشتن (منفی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Will it matter if I’m a little late?","translation":"اگر کمی دیر بیام مهم است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000213104.mp3"},{"sentence":"If I have to stay late at work tonight, it won’t matter because we can go out another night.","translation":"اگر مجبور باشم امشب تا دیر وقت سر کار بمانم، مهم نیست، زیرا می توانیم یک شب دیگر بیرون برویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000213101.mp3"},{"sentence":"It doesn’t matter what you wear, as long as you look neat and tidy.","translation":"مهم نیست چه می پوشید، به شرطی که مرتب و مرتب به نظر برسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000213110.mp3"},{"sentence":"Does it matter what I think?","translation":"آیا مهم است که من چه فکر می کنم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000213111.mp3"},{"sentence":"It does not matter that the gun was in fact unloaded.","translation":"مهم نیست که اسلحه در واقع خالی بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001825417.mp3"},{"sentence":"Do you think it matters that the cups and saucers don’t match?","translation":"آیا فکر می کنید مهم است که فنجان ها و نعلبکی ها مطابقت نداشته باشند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001825418.mp3"},{"sentence":"Just give me $5 – it doesn’t matter about the rest.","translation":"فقط 5 دلار به من بدهید - بقیه مهم نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000213107.mp3"},{"sentence":"He had lost many of the people who mattered to him.","translation":"او بسیاری از افرادی را که برایش مهم بودند از دست داده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000213114.mp3"},{"sentence":"It mattered a great deal to her what other people thought of her.","translation":"برای او بسیار مهم بود که دیگران در مورد او چه فکر می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000213118.mp3"},{"sentence":"I don’t think it matters much what you study.","translation":"فکر نمی کنم خیلی مهم باشد که شما چه می خوانید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001825425.mp3"},{"sentence":"campaigning on issues that really matter","translation":"مبارزات انتخاباتی در مورد موضوعاتی که واقعاً مهم هستند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001825426.mp3"},{"sentence":"All that matters is that you are safe.","translation":"تنها چیزی که مهم است این است که شما در امان باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00580.mp3"},{"sentence":"Money was the only thing which mattered to him.","translation":"پول تنها چیزی بود که برایش اهمیت داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00581.mp3"},{"sentence":"I don’t care what it looks like – what matters is that it works.","translation":"برای من مهم نیست که چگونه به نظر می رسد - مهم این است که کار می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001825429.mp3"},{"sentence":"At last she was with the man she loved and nothing else mattered .","translation":"بالاخره او با مردی بود که دوستش داشت و هیچ چیز دیگری مهم نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001825433.mp3"},{"sentence":"She said very little during the meal. Not that it mattered (= it was not important ) .","translation":"او در طول غذا خیلی کم گفت. نه اینکه مهم بود (= مهم نبود ) .","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001825437.mp3"}]'::jsonb,16),
