('9b68095d-547d-5f17-989a-53e1b600b7bf','fc4d2cbb-5c2f-584c-9e7c-4e618ee898fc',6,null,null,'informal','thinking or behaving in a way that seems crazy or strange','[ not before noun ]',null,'فکر کردن یا رفتار کردن به روشی که دیوانه کننده یا عجیب به نظر می رسد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He must be mental!","translation":"او باید روانی باشد!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000222173.mp3"}]'::jsonb,1),
('669d4237-ed7c-56a2-9490-80893156bef1','fc4d2cbb-5c2f-584c-9e7c-4e618ee898fc',7,null,null,'informal','very confused , busy , or exciting',null,null,'بسیار گیج، شلوغ، یا هیجان انگیز','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I had a mental time at the festival – there was all sorts of crazy stuff going on!","translation":"من در جشنواره زمان ذهنی داشتم - همه جور چیزهای دیوانه کننده ای در جریان بود!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00587.mp3"}]'::jsonb,1),
('1e4c8c9b-c494-550e-a985-c41417447b8f','613edca0-824e-5650-bf89-cde798dd4400',1,null,null,'spoken & written','used to emphasize how small or unimportant something or someone is',null,null,'فقط، صرفاً؛ به‌تنهایی (بدون بیشتر)',array['only']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He’s merely a boy – you can’t expect him to understand.","translation":"او فقط یک پسر است - نمی توانید از او انتظار داشته باشید که بفهمد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000223268.mp3"}]'::jsonb,1),
('346d94e3-e04e-55b3-aefa-e3c9f5404213','613edca0-824e-5650-bf89-cde798dd4400',2,null,null,'spoken & written','used to emphasize that nothing more than what you say is involved',null,null,'برای تاکید بر اینکه چیزی بیشتر از آنچه شما می گویید دخیل نیست',array['just']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We’re merely good friends.","translation":"ما فقط دوستان خوبی هستیم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000223274.mp3"},{"sentence":"He merely shrugged and walked away.","translation":"فقط شانه بالا انداخت و رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001564355.mp3"}]'::jsonb,2),
