('ace1a2a2-1831-58b5-a846-57be75519596','409c2173-8bef-525e-9c73-89b57c2c2022',1,null,null,'spoken & written','a mobile phone',null,null,'تلفن همراه، موبایل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Give me a call on my mobile.","translation":"با موبایلم تماس بگیر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001648208.mp3"},{"sentence":"Have you got my mobile number?","translation":"شماره موبایل من را دارید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001648209.mp3"}]'::jsonb,2),
('455cb60e-5961-5d67-ad16-76935b39b378','409c2173-8bef-525e-9c73-89b57c2c2022',2,null,null,'spoken & written','a decoration made of small objects tied to wires or string which is hung up so that the objects move when air blows around them',null,null,'تزئینی ساخته شده از اشیاء کوچکی که به سیم یا ریسمان بسته شده است و به گونه ای آویزان می شود که هنگام وزش هوا در اطراف آنها حرکت کنند.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('707db629-9fa0-5c97-b070-7388a6677ed3','8d1fe18f-bcde-55ad-a2b1-7203145f653b',1,null,null,'spoken & written','not fixed in one position, and easy to move and use in different places',null,null,'در یک موقعیت ثابت نیست و به راحتی قابل جابجایی و استفاده در مکان های مختلف است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"mobile air-conditioners","translation":"تهویه مطبوع سیار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000204159.mp3"}]'::jsonb,1),
('ece3a18a-e34c-5519-888d-c7fda2e1af07','8d1fe18f-bcde-55ad-a2b1-7203145f653b',2,null,null,'spoken & written','moving or able to move from one job, area, or social class to another',null,null,'حرکت یا توانایی انتقال از یک شغل، منطقه، یا طبقه اجتماعی به دیگری','{}'::text[],'{}'::text[],array['highly mobile (= very mobile ) We now live in a highly mobile society.','upwardly mobile (= moving up to a higher social class ) The restaurant''s customers are mainly upwardly mobile young professionals.','socially mobile (= moving from one social class to another, especially to a higher social class ) Children today are even less likely to be socially mobile.']::text[],'[{"sentence":"a more mobile workforce","translation":"نیروی کار متحرک تر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001648204.mp3"},{"sentence":"People these days are much more socially mobile .","translation":"مردم این روزها از نظر اجتماعی تحرک بسیار بیشتری دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000204169.mp3"},{"sentence":"an upwardly mobile (= moving to a higher social scale ) professional","translation":"یک حرفه ای متحرک رو به بالا (= حرکت به یک مقیاس اجتماعی بالاتر).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817583.mp3"}]'::jsonb,3),
('3f83bdea-f9fc-5ba5-8772-47b2c7f768a9','8d1fe18f-bcde-55ad-a2b1-7203145f653b',3,null,null,'spoken & written','able to move or travel easily',null,null,'می تواند به راحتی حرکت کند یا سفر کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s more mobile now that she has her own car.","translation":"او اکنون که ماشین خودش را دارد تحرک بیشتری دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000204155.mp3"}]'::jsonb,1),
