('29aab94f-1b4f-55f7-8bba-ae72f06e53ab','0434c56f-744f-5a52-b97c-ee1276f46d22',6,null,null,'spoken & written',null,null,'the last moment','لحظه، دم؛ اهمیت (لحظه)؛ دم (بازی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
