('de288091-7bdc-5e2c-bbba-9760bc638d7e','2df2d98a-0a8d-5baa-88b0-2e04679d9c16',2,'moving your head or hand','حرکت دادن سر یا دست','spoken & written','a single movement of your head or hand, especially one made in order to communicate something','[ countable ]',null,'یک حرکت سر یا دست، به خصوص حرکتی که برای برقراری ارتباط با چیزی انجام می شود',array['gesture']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He summoned the waiter with a motion of his hand.","translation":"با حرکت دست گارسون را احضار کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001555037.mp3"},{"sentence":"Doyle glanced back at Bodie, and made a slight motion with his head.","translation":"دویل نگاهی به بادی انداخت و حرکتی ملایم با سرش انجام داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001555038.mp3"}]'::jsonb,2),
('07dd7a50-2adf-54f7-9b92-da1c42d03dda','2df2d98a-0a8d-5baa-88b0-2e04679d9c16',3,'suggestion at a meeting','پیشنهاد در یک جلسه','spoken & written','a proposal that is made formally at a meeting, and then is usually decided on by voting','[ countable ]',null,'پیشنهادی که به طور رسمی در یک جلسه مطرح می شود و سپس معمولاً با رأی گیری در مورد آن تصمیم گیری می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The motion was defeated by 201 votes to 159.","translation":"این طرح با 201 رای موافق و 159 رای مخالف شکست خورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001555044.mp3"},{"sentence":"We will now vote on the motion that membership charges should rise by 15%.","translation":"ما اکنون به پیشنهادی رای خواهیم داد که هزینه های عضویت باید 15 درصد افزایش یابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000211415.mp3"},{"sentence":"The motion was carried unanimously.","translation":"این طرح به اتفاق آرا تصویب شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000211419.mp3"},{"sentence":"I urge you to support this motion .","translation":"من از شما می خواهم که از این طرح حمایت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001555052.mp3"},{"sentence":"I’d like to propose a motion to move the weekly meetings to Thursdays.","translation":"می‌خواهم پیشنهادی برای انتقال جلسات هفتگی به پنجشنبه‌ها ارائه کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000211423.mp3"},{"sentence":"The motion was seconded (= formally supported ) by Mr Levin.","translation":"این پیشنهاد توسط آقای لوین ثانویه شد (= رسماً حمایت شد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758883.mp3"},{"sentence":"The attorneys filed a motion (= made a proposal in a court ) for a temporary restraining order.","translation":"وکلای دادگستری (= پیشنهادی در دادگاه ارائه کردند) برای قرار منع موقت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817454.mp3"}]'::jsonb,7),
