('4c8b6c46-75c5-5581-89ef-7c59ddea62cf','b36bb47f-f98d-5560-8a8f-66467c11ca2e',1,null,null,'spoken & written','to kill someone deliberately and illegally',null,null,'کشتن عمدی و غیرقانونی کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was convicted of murdering a policeman.","translation":"او به قتل یک پلیس محکوم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000196791.mp3"},{"sentence":"Thousands of civilians were brutally murdered during the civil war.","translation":"هزاران غیرنظامی در جریان جنگ داخلی به طرز وحشیانه ای به قتل رسیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000196792.mp3"},{"sentence":"the murdered man","translation":"مرد مقتول","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000196793.mp3"}]'::jsonb,3),
('930b8675-cdc6-50fd-99ec-7ac3c67b67ee','b36bb47f-f98d-5560-8a8f-66467c11ca2e',2,null,null,'informal','to spoil a song , play etc by performing it very badly',null,null,'برای خراب کردن یک آهنگ، پخش و غیره با اجرای بسیار بد آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s a good song, but they murdered it.","translation":"این آهنگ خوبی است، اما آنها آن را به قتل رساندند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000196804.mp3"}]'::jsonb,1),
