('01f37816-de81-531a-8ab0-9809995a63a7','aab8910e-a633-5812-a810-a1c273cd9c89',1,null,null,'spoken & written','used by the person speaking or writing to show that they are affected by their own action',null,null,'خودم — ضمیر انعکاسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I blame myself for what has happened.","translation":"من خودم را به خاطر اتفاقی که افتاده سرزنش می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837255.mp3"},{"sentence":"I can look after myself.","translation":"من می توانم از خودم مراقبت کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837256.mp3"},{"sentence":"I’m making myself a sandwich.","translation":"دارم برای خودم ساندویچ درست میکنم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837257.mp3"}]'::jsonb,3),
