('091ac18d-a0e1-5729-96ae-2359d34466fe','7894f16e-5d80-5f77-9ace-0fc813459437',4,'ideas/attitudes','ایده ها/نگرش ها','spoken & written','a narrow attitude or way of looking at a situation is too limited and does not consider enough possibilities',null,'narrow-minded','نگرش یا نگاه محدود به یک موقعیت بسیار محدود است و امکانات کافی را در نظر نمی گیرد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You’ve got a very narrow view of life.","translation":"شما دید بسیار محدودی از زندگی دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535408.mp3"},{"sentence":"Some teachers have a narrow vision of what art is.","translation":"برخی از معلمان دید محدودی نسبت به هنر دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000233366.mp3"}]'::jsonb,2),
