('1114c92f-c2e1-5ff4-bf78-cb96f415ef95','177b14f3-d315-5ec3-9461-01bc0816fc31',3,null,null,'not polite','a word used by white people in the past to refer to the people who lived in America, Africa, southern Asia etc before European people arrived, now considered offensive','[ usually plural ]',null,'واژه‌ای که در گذشته توسط سفیدپوستان برای اشاره به افرادی که قبل از ورود اروپایی‌ها در آمریکا، آفریقا، آسیای جنوبی و غیره زندگی می‌کردند، استفاده می‌کردند که اکنون توهین‌آمیز تلقی می‌شود.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was not certain whether the natives were friendly.","translation":"او مطمئن نبود که بومیان دوستانه هستند یا خیر.","audio_url":null}]'::jsonb,1),
('e2d70ffe-86fe-5af1-9ff6-7af603357b02','177b14f3-d315-5ec3-9461-01bc0816fc31',4,null,null,'spoken & written','a plant or animal that grows or lives naturally in a place',null,null,'گیاه یا حیوانی که به طور طبیعی در مکانی رشد می کند یا زندگی می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The bear was once a native of Britain.","translation":"این خرس زمانی اهل بریتانیا بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234193.mp3"}]'::jsonb,1),
('526b42a6-f271-59e1-b827-17ee3f8865f8','c897dd41-3ad2-59c4-9923-b7c3ca940085',1,'plants/animals etc','گیاهان / حیوانات و غیره','spoken & written','everything in the physical world that is not controlled by humans , such as wild plants and animals, earth and rocks , and the weather','[ uncountable ]',null,'طبیعت، حیات وحش؛ سرشت؛ جنس (کار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We grew up in the countryside, surrounded by the beauties of nature.","translation":"ما در حومه شهر و در محاصره زیبایی های طبیعت بزرگ شدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234682.mp3"},{"sentence":"nature conservation","translation":"حفاظت از طبیعت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556112.mp3"},{"sentence":"The inhabitants of the island fight a constant battle against the forces of nature.","translation":"ساکنان جزیره در نبردی دائمی با نیروهای طبیعت می جنگند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556118.mp3"},{"sentence":"All these materials are found in nature.","translation":"همه این مواد در طبیعت یافت می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556121.mp3"},{"sentence":"Disease is nature’s way of keeping the population down.","translation":"بیماری روش طبیعت برای پایین نگه داشتن جمعیت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556122.mp3"},{"sentence":"the power of nature","translation":"قدرت طبیعت","audio_url":null}]'::jsonb,6),
('3833dae7-c151-556b-b7d6-c868aa5f2eef','c897dd41-3ad2-59c4-9923-b7c3ca940085',2,'somebody’s character','شخصیت کسی','spoken & written','someone’s character','[ countable, uncountable ]',null,'شخصیت کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a child with a happy, easy-going nature","translation":"کودکی با طبیعتی شاد و راحت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234689.mp3"},{"sentence":"It’s just not in Jane’s nature to lie.","translation":"دروغ گفتن در ذات جین نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762875.mp3"},{"sentence":"She was by nature a very affectionate person.","translation":"او ذاتاً فردی بسیار مهربان بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556131.mp3"},{"sentence":"I tried appealing to his better nature (= his feelings of kindness ) but he wouldn’t agree to help us.","translation":"سعی کردم به ذات بهتر او (= احساس مهربانی او) متوسل شوم، اما او حاضر نشد به ما کمک کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556132.mp3"},{"sentence":"Of course she’s jealous – it’s only human nature (= the feelings and ways of behaving that all people have ) .","translation":"البته او حسود است - این فقط طبیعت انسانی است (= احساسات و شیوه های رفتاری که همه مردم دارند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556137.mp3"}]'::jsonb,5),
('81a5a822-d40e-566f-a612-e5d9cd780444','c897dd41-3ad2-59c4-9923-b7c3ca940085',3,'qualities of something','کیفیت های چیزی','spoken & written','the qualities or features that something has','[ singular, uncountable ]',null,'کیفیت ها یا ویژگی هایی که چیزی دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They asked a lot of questions about the nature of our democracy.","translation":"آنها سوالات زیادی در مورد ماهیت دموکراسی ما پرسیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556144.mp3"},{"sentence":"He examined the nature of the relationship between the two communities.","translation":"او ماهیت روابط بین دو جامعه را بررسی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816649.mp3"},{"sentence":"The exact nature of the problem is not well understood.","translation":"ماهیت دقیق مشکل به خوبی درک نشده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556147.mp3"},{"sentence":"Any government funding would be temporary in nature.","translation":"هر گونه بودجه دولتی ماهیت موقتی خواهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556150.mp3"},{"sentence":"Capitalist society is by its very nature unstable.","translation":"جامعه سرمایه داری ذاتاً ناپایدار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556151.mp3"}]'::jsonb,5),
('aacb1854-eaf3-518a-82e1-a058c9b4d8f2','c897dd41-3ad2-59c4-9923-b7c3ca940085',4,'type','نوع','spoken & written','a particular kind of thing','[ singular ]',null,'نوع خاصی از چیز','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The support being given is of a practical nature.","translation":"حمایت ارائه شده ماهیت عملی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234721.mp3"},{"sentence":"I never trouble myself with questions of that nature.","translation":"من هرگز خودم را با سوالاتی از این قبیل مشکل نمی کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234725.mp3"}]'::jsonb,2),
