('f5d76696-d2aa-5d42-9c90-94a41a99f0e2','8b725599-1e34-59bb-b66b-127050425406',1,null,null,'spoken & written','almost, but not quite or not completely',null,null,'تقریباً، نزدیک به (نه کامل)',array['almost']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It took nearly two hours to get here.","translation":"نزدیک به دو ساعت طول کشید تا به اینجا رسیدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000235561.mp3"},{"sentence":"Michelle’s nearly twenty.","translation":"میشل نزدیک به بیست سال دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000235562.mp3"},{"sentence":"Is the job nearly finished?","translation":"آیا کار تقریباً تمام شده است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000235563.mp3"},{"sentence":"Louise is nearly as tall as her mother.","translation":"لوئیز تقریباً به اندازه مادرش قد دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000235565.mp3"},{"sentence":"I nearly always go home for lunch.","translation":"من تقریبا همیشه برای ناهار به خانه می روم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556334.mp3"},{"sentence":"He very nearly died.","translation":"خیلی نزدیک بود بمیرد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556338.mp3"}]'::jsonb,6),
