('8ad0fee9-a61f-5fdb-bdef-28a9c27ef615','ded00bb0-5f29-5d9f-a73e-be8a29167947',1,'well','خوب','spoken & written','in a satisfactory , pleasant , or attractive way',null,null,'خوب، به‌نحو خوشایند؛ به‌طور منظم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was handsome and nicely dressed.","translation":"خوش تیپ و خوش لباس بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001701911.mp3"},{"sentence":"The table fits in nicely with the rest of the furniture.","translation":"میز به خوبی با بقیه مبلمان هماهنگ می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000241784.mp3"},{"sentence":"The wound healed up nicely.","translation":"زخم به خوبی خوب شد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001760900.mp3"},{"sentence":"The garden’s coming along very nicely now (= it is growing well ) .","translation":"باغ اکنون بسیار خوب پیش می‌آید (= به خوبی رشد می‌کند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001701912.mp3"}]'::jsonb,4),
('f7fedec8-80c8-5201-bc73-211a1da85198','ded00bb0-5f29-5d9f-a73e-be8a29167947',2,'in a pleasant/friendly way','به روشی دلپذیر/دوستانه','spoken & written','in a pleasant, polite , or friendly way',null,null,'به شیوه ای خوشایند، مودبانه یا دوستانه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m sure he’ll help if you ask him nicely.","translation":"مطمئنم اگر خوب از او بخواهید کمک خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001701919.mp3"}]'::jsonb,1),
