('3f3f9e39-b24c-5fc7-8c51-3af58871bd7c','ded00bb0-5f29-5d9f-a73e-be8a29167947',5,'exactly','دقیقا','formal','exactly or carefully',null,null,'دقیقا یا با دقت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a nicely calculated distance","translation":"یک فاصله خوب محاسبه شده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001701926.mp3"}]'::jsonb,1),
('f7db8f6a-4c29-5652-90ea-41c656a8018a','766e535f-26ae-5fcf-836e-ffd5e89f0536',1,null,null,'spoken & written','not anyone',null,null,'هیچ‌کس، کسی (نفی)',array['nobody']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"No one likes being criticized.","translation":"هیچ کس دوست ندارد مورد انتقاد قرار بگیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246080.mp3"},{"sentence":"There’s no one else I really want to invite apart from you.","translation":"هیچ کس دیگری نیست که واقعاً بخواهم غیر از شما دعوت کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246081.mp3"},{"sentence":"Has no one phoned about the car?","translation":"کسی در مورد ماشین زنگ نزده؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246082.mp3"},{"sentence":"No one can say I didn’t warn you.","translation":"هیچ کس نمی تواند بگوید من به شما هشدار ندادم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246083.mp3"}]'::jsonb,4),
('618cb9c6-b2a1-51a5-a3b4-8e903d091bfe','7f1d52ed-72c9-5061-9f35-491b24a0dd21',1,null,null,'spoken & written','used to emphasize that you will not agree or be able to do something',null,null,'به‌هیچ‌وجه، اصلاً (رد قطعی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Are you going to offer to work over the weekend?’ ‘No way!’","translation":"«آیا می‌خواهید در آخر هفته کار کنید؟» «به هیچ وجه!»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000249060.mp3"},{"sentence":"No way will we be finished by five o''clock.","translation":"به هیچ وجه تا ساعت پنج کارمان تمام نمی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000249061.mp3"},{"sentence":"There’s no way I’m going to pay £500 just for a weekend in Paris.","translation":"هیچ راهی وجود ندارد که من فقط برای یک تعطیلات آخر هفته در پاریس 500 پوند بپردازم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000249064.mp3"}]'::jsonb,3),
('1d0fc955-35bc-53dc-ad3c-9137b0cce727','b6324abd-fb0e-5177-9904-9499f7810ead',1,null,null,'spoken & written','used to say that you will definitely not do or allow something',null,null,'می گفت قطعا کاری را انجام نمی دهید یا اجازه نمی دهید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Can I borrow your car?’ ‘No way!’","translation":"«می‌توانم ماشینت را قرض بگیرم؟» «به هیچ وجه!»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001802416.mp3"},{"sentence":"There’s no way I’ll ever get married again.","translation":"هیچ راهی وجود ندارد که من هرگز دوباره ازدواج کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001802417.mp3"},{"sentence":"She’s 45? No way!","translation":"او 45 سال دارد؟ به هیچ وجه!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001802427.mp3"}]'::jsonb,3),
('4e2382d4-0b93-50b2-beee-a10787fa598b','9fa9fb9e-070f-5b24-b019-ef169392a00c',1,null,null,'spoken & written','no one',null,null,'هیچ‌کس، هیچ‌کس (نفی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I knocked on the door but nobody answered.","translation":"در زدم اما کسی جواب نداد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000243764.mp3"}]'::jsonb,1),
('d8ab4d83-a614-50da-ac5a-921eb23d86e9','9fa9fb9e-070f-5b24-b019-ef169392a00c',2,null,null,'spoken & written',null,null,'like nobody’s business','هیچ‌کس، هیچ‌کس (نفی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('17ddf759-51e9-5fa8-9bd1-4660e37d507a','bd572c78-188c-57ff-bad6-3281089c984a',1,null,null,'spoken & written','someone who is not important and has no influence',null,null,'کسی که مهم نیست و تاثیری ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I was a nothing and a nobody with everything to prove.","translation":"من یک هیچ و یک هیچکس بودم که همه چیز برای اثبات داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000243792.mp3"}]'::jsonb,1),
('6b8d51ca-4f12-5a4b-95db-5e7029db1127','3351ae38-11d6-5262-90b7-317bd4445b61',1,null,null,'spoken & written','usual , typical , or expected',null,null,'عادی، طبیعی؛ معمولی (پوست)؛ مستقیم (دما)','{}'::text[],'{}'::text[],array['completely normal The test results came back, and everything was completely normal.','perfectly normal (= completely normal ) Her reaction to the news was perfectly normal.','quite normal (= completely normal ) He sounded quite normal when he phoned.','fairly/pretty normal His family all seem pretty normal.','a normal life All I want is to lead a happy, normal life.','as normal (= used to emphasize that something happens very regularly ) John and Liz were late as normal.','in/under normal circumstances Under normal circumstances, you would have to pay to go into the exhibition.','in the normal way The results will be posted to you in the normal way.']::text[],'[{"sentence":"A normal working week is 40 hours.","translation":"یک هفته کاری عادی 40 ساعت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557145.mp3"},{"sentence":"It’s normal to feel nervous before an exam.","translation":"طبیعی است که قبل از امتحان احساس عصبی کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246232.mp3"},{"sentence":"Her room was untidy, but that was quite normal.","translation":"اتاق او نامرتب بود، اما این کاملاً عادی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557150.mp3"},{"sentence":"She was assessed in the normal way , and placed on the waiting list.","translation":"او به روش عادی ارزیابی شد و در لیست انتظار قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246229.mp3"},{"sentence":"All I want is to lead a normal life .","translation":"تنها چیزی که می خواهم این است که یک زندگی عادی داشته باشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557141.mp3"}]'::jsonb,5),
('a070a4cc-a5b8-500c-af8e-24582277546d','3351ae38-11d6-5262-90b7-317bd4445b61',2,null,null,'spoken & written','someone who is normal is mentally and physically healthy and does not behave strangely',null,null,'فردی که طبیعی است از نظر روحی و جسمی سالم است و رفتار عجیبی ندارد','{}'::text[],'{}'::text[],array['completely normal The test results came back, and everything was completely normal.','perfectly normal (= completely normal ) Her reaction to the news was perfectly normal.','quite normal (= completely normal ) He sounded quite normal when he phoned.','fairly/pretty normal His family all seem pretty normal.','a normal life All I want is to lead a happy, normal life.','as normal (= used to emphasize that something happens very regularly ) John and Liz were late as normal.','in/under normal circumstances Under normal circumstances, you would have to pay to go into the exhibition.','in the normal way The results will be posted to you in the normal way.']::text[],'[{"sentence":"He seems a perfectly normal little boy.","translation":"او یک پسر کوچک کاملاً عادی به نظر می رسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000246245.mp3"},{"sentence":"They can’t be normal to do something like that.","translation":"آنها نمی توانند برای انجام چنین کاری عادی باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557154.mp3"}]'::jsonb,2),
('87fbb7dc-69dc-595e-9e67-70bbcdea472f','6b9cca34-4bde-5034-8021-14e154e60fcd',1,null,null,'spoken & written','the usual state, level, or amount',null,null,'حالت، سطح یا مقدار معمولی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Thankfully, train services are now back to normal .","translation":"خوشبختانه، خدمات قطار اکنون به حالت عادی بازگشته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557201.mp3"},{"sentence":"Slowly her heartbeat returned to normal .","translation":"آرام آرام ضربان قلبش به حالت عادی برگشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557205.mp3"},{"sentence":"Car sales are still below normal for the time of year.","translation":"فروش خودرو همچنان پایین تر از حد نرمال برای فصل سال است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557211.mp3"},{"sentence":"The journey took longer than normal.","translation":"سفر بیش از حد معمول طول کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816997.mp3"}]'::jsonb,4),
('859d177f-af30-5ab8-8fe6-cb308d299701','64e6a4fe-51a0-5e31-8187-18fbf068ff33',1,null,null,'spoken & written','if you notice something or someone, you realize that they exist , especially because you can see, hear , or feel them',null,null,'متوجه شدن، توجه کردن (به)؛ خبر شدن (از)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He noticed a woman in a black dress sitting across from him.","translation":"او متوجه زنی با لباس مشکی شد که روبروی او نشسته بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572975.mp3"},{"sentence":"I didn’t notice any smoke.","translation":"من متوجه دودی نشدم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572976.mp3"},{"sentence":"Have you noticed any change in him?","translation":"آیا تغییری در او مشاهده کرده اید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572977.mp3"},{"sentence":"I noticed that her hands were shaking.","translation":"متوجه شدم دستانش می لرزند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572981.mp3"},{"sentence":"He never seems to notice when people take advantage of him.","translation":"به نظر می رسد هرگز متوجه نمی شود که مردم از او سوء استفاده می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572978.mp3"},{"sentence":"She hadn’t noticed before quite how grey his hair was.","translation":"قبلاً متوجه نشده بود که موهای او چقدر خاکستری است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572984.mp3"},{"sentence":"Did you notice him leaving the party early?","translation":"آیا متوجه خروج او از مهمانی زودهنگام شده اید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572987.mp3"},{"sentence":"I notice you’re wearing glasses.","translation":"متوجه شدم که عینکی زده ای","audio_url":null}]'::jsonb,8),
('92237f1b-5386-521e-ab44-4b16879e699b','64e6a4fe-51a0-5e31-8187-18fbf068ff33',2,null,null,'spoken & written',null,null,'be noticed/get (somebody) noticed','متوجه شدن، توجه کردن (به)؛ خبر شدن (از)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('f78613d6-666a-57ff-9a0b-a8fa321c3d5f','64e6a4fe-51a0-5e31-8187-18fbf068ff33',3,null,null,'spoken & written',null,null,'somebody can’t help noticing something','متوجه شدن، توجه کردن (به)؛ خبر شدن (از)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0e39aacc-0b47-56ff-8fdb-952e5d604671','271a0b9a-b0f1-5f36-858d-6e080fac652b',1,'attention','توجه','spoken & written','when you notice or pay attention to someone or something','[ uncountable ]',null,'توجه، توجه (کار)؛ اعلام (رسمی)؛ اطلاع (پیشاپیش)','{}'::text[],'{}'::text[],array['take notice (= pay attention to something ) I began to take notice when the subject of money came up.','take no notice/not take any notice (= ignore something or someone ) The other passengers took no notice of what was happening.','come to somebody’s notice (= be noticed by someone ) This problem first came to our notice last summer.','escape somebody’s notice (= not be noticed by someone ) It had not escaped his notice that Phil seemed interested in Jean.','bring something to somebody’s notice (= tell someone about something ) It has been brought to my notice that employees are smoking in the restrooms.','attract notice (= be noticed by other people ) She didn’t want to attract notice, so she dressed very plainly.']::text[],'[{"sentence":"I waved but they took no notice .","translation":"دست تکان دادم اما آنها متوجه نشدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573003.mp3"},{"sentence":"I did not take much notice of her suggestions.","translation":"من زیاد به پیشنهادات او توجه نکردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764484.mp3"},{"sentence":"I hope you’ll take notice of what I’m going to tell you.","translation":"امیدوارم به آنچه که به شما می گویم توجه داشته باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000248278.mp3"},{"sentence":"This problem may have escaped your notice so far (= you may not have noticed it ) .","translation":"این مشکل ممکن است تا کنون از چشم شما دور مانده باشد (= ممکن است متوجه آن نشده باشید).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573011.mp3"},{"sentence":"This never came to my notice (= I never knew about this ) .","translation":"این هرگز متوجه من نشد (= من هرگز در مورد این خبر نداشتم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573018.mp3"},{"sentence":"There are several important matters that I’d like to bring to your notice (= that I would like you to know about ) .","translation":"چندین موضوع مهم وجود دارد که می خواهم به اطلاع شما برسانم (= مایلم شما در مورد آنها بدانید).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573025.mp3"}]'::jsonb,6),
('6ca95860-401e-5d3e-ba8c-b64412d16245','271a0b9a-b0f1-5f36-858d-6e080fac652b',2,'on paper','روی کاغذ','spoken & written','a written or printed statement that gives information or a warning to people','[ countable ]',null,'یک بیانیه کتبی یا چاپی که اطلاعات یا هشداری به مردم می دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The notice on the wall said ‘No smoking’.","translation":"آگهی روی دیوار نوشته بود «سیگار ممنوع».","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000248284.mp3"},{"sentence":"I’ll put up a notice about the meeting.","translation":"من اطلاعیه ای در مورد جلسه ارسال می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000248285.mp3"},{"sentence":"obituary notices (= about people who have just died ) in the newspaper","translation":"آگهی های ترحیم (= در مورد افرادی که به تازگی فوت کرده اند) در روزنامه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573032.mp3"}]'::jsonb,3),
('463a3937-9bb1-5e35-84d9-3dc816a4f321','271a0b9a-b0f1-5f36-858d-6e080fac652b',3,'time to prepare','زمان آماده سازی','spoken & written','information or a warning about something that is going to happen','[ uncountable ]',null,'اطلاعات یا هشدار در مورد چیزی که قرار است رخ دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"These rules are subject to change without notice.","translation":"این قوانین بدون اطلاع قبلی قابل تغییر هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764494.mp3"},{"sentence":"They didn’t give me sufficient notice .","translation":"آنها به من اطلاع کافی ندادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573039.mp3"},{"sentence":"When you’re on the mailing list, you’ll receive advance notice of upcoming events.","translation":"وقتی در لیست پستی هستید، از رویدادهای آتی اطلاعیه قبلی دریافت خواهید کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764497.mp3"},{"sentence":"They closed the factory, giving the workers only a week’s notice.","translation":"آنها کارخانه را تعطیل کردند و فقط یک هفته به کارگران اخطار دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000248295.mp3"},{"sentence":"Firefighters were prepared to rush out at a moment’s notice .","translation":"آتش‌نشانان آماده شدند تا در یک لحظه به بیرون بروند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573044.mp3"},{"sentence":"his failure to give notice of his intention to alter the property","translation":"عدم اطلاع او از قصد خود برای تغییر ملک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764500.mp3"},{"sentence":"I’ve been given notice to quit my flat (= I have been told that I must leave by a certain date ) .","translation":"به من اخطار داده شده است که آپارتمان خود را ترک کنم (= به من گفته شده است که باید تا تاریخ معینی آنجا را ترک کنم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573048.mp3"},{"sentence":"Union members served strike notice (= warned that they would go on strike ) late last night.","translation":"اعضای اتحادیه در اواخر شب گذشته اخطار اعتصاب (= هشدار دادند که اعتصاب خواهند کرد) ارسال کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573053.mp3"}]'::jsonb,8),
('77ef5286-7a35-5750-a398-03a9fc6f66c2','271a0b9a-b0f1-5f36-858d-6e080fac652b',4,null,null,'spoken & written',null,null,'until further notice','توجه، توجه (کار)؛ اعلام (رسمی)؛ اطلاع (پیشاپیش)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('8fbe0414-5101-54d8-8635-bcf3378d8801','271a0b9a-b0f1-5f36-858d-6e080fac652b',5,null,null,'spoken & written',null,null,'hand in your notice/give (your) notice','توجه، توجه (کار)؛ اعلام (رسمی)؛ اطلاع (پیشاپیش)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ad47876d-390d-54c9-95d4-31ee6ae58173','271a0b9a-b0f1-5f36-858d-6e080fac652b',6,null,null,'spoken & written',null,null,'at short notice','توجه، توجه (کار)؛ اعلام (رسمی)؛ اطلاع (پیشاپیش)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('76e24e40-a8b6-5f59-ac63-15276412877f','271a0b9a-b0f1-5f36-858d-6e080fac652b',7,'book/play etc','کتاب / نمایشنامه و غیره','spoken & written','a statement of opinion , especially one written for a newspaper or magazine , about a new play, book, film etc','[ countable usually plural ]',null,'اظهار نظر، به ویژه نظری که برای یک روزنامه یا مجله نوشته شده است، در مورد یک نمایشنامه، کتاب، فیلم جدید و غیره',array['review']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The new play got mixed notices (= some good, some bad ) in the newspapers.","translation":"نمایشنامه جدید اعلامیه های متفاوتی (= برخی خوب، برخی بد) در روزنامه ها دریافت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573069.mp3"}]'::jsonb,1),
('ef72ccdf-0234-5276-b719-d797ad499af3','0ef31e89-fa61-5e27-948a-021865657612',1,null,null,'spoken & written','an idea, belief, or opinion',null,null,'فکر، تصور؛ باور؛ عقیده (بدون مدرک)','{}'::text[],'{}'::text[],array['have a notion He didn’t have a clear notion of what he had to do.','accept a notion Probably 95% of scientists now accept the notion that human activity is causing climate change.','support a notion There is no evidence to support the notion that girls are treated better than boys in school.','reinforce a notion (= make an idea stronger or easier to believe ) The research reinforces the notion that fathers have an important role in their children’s lives.','challenge/dispute a notion Copernicus challenged the notion that the Sun goes around the Earth.','reject/dismiss a notion Aristotle rejected the notion that the body and the soul are separate.','a vague notion (= an unclear idea ) He had only a vague notion of what might happen next.','an absurd/ridiculous notion They had the ridiculous notion that they could make a living from singing.','a simple notion You cannot rate the project according to a simple notion of ‘value for money’: there are too many factors involved.','an abstract notion In art, how can you represent abstract notions such as peace or justice?','a romantic notion (= one that is based on how you want something to be, not how it is in real life ) He rejected the romantic notion of rugby as a game for gentlemen.','a preconceived notion (= an idea that you have before you have enough knowledge or experience ) The police were accused of twisting the evidence to meet their preconceived notion of his guilt.','an accepted/received notion (= an idea that most people believe ) These women challenged accepted notions of female roles in society.','the whole notion of something (= used to emphasize that you are talking about a lot of related ideas, not just one specific idea ) The movie makes us question the whole notion of what makes a hero.','not have the faintest/foggiest notion (= not know or understand something at all ) He had not the foggiest notion how far he might have to walk.']::text[],'[{"sentence":"misguided notions of male superiority","translation":"تصورات نادرست برتری مرد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000248461.mp3"},{"sentence":"The traditional notion of marriage goes back thousands of years.","translation":"مفهوم سنتی ازدواج به هزاران سال پیش برمی گردد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573122.mp3"},{"sentence":"She had only a vague notion of what she wanted to do.","translation":"او فقط تصور مبهمی از کاری که می خواست انجام دهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573109.mp3"},{"sentence":"the notion that human beings are basically good","translation":"این تصور که انسان اساساً خوب است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764522.mp3"},{"sentence":"She had no notion what he meant.","translation":"او نمی دانست منظور او چیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764523.mp3"},{"sentence":"They reject the notion of group guilt.","translation":"آنها مفهوم گناه گروهی را رد می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573119.mp3"}]'::jsonb,6),
('9a676074-d86c-53ac-bdbf-ac629df6bcc5','0ef31e89-fa61-5e27-948a-021865657612',2,null,null,'spoken & written',null,null,'notions','فکر، تصور؛ باور؛ عقیده (بدون مدرک)','{}'::text[],'{}'::text[],array['have a notion He didn’t have a clear notion of what he had to do.','accept a notion Probably 95% of scientists now accept the notion that human activity is causing climate change.','support a notion There is no evidence to support the notion that girls are treated better than boys in school.','reinforce a notion (= make an idea stronger or easier to believe ) The research reinforces the notion that fathers have an important role in their children’s lives.','challenge/dispute a notion Copernicus challenged the notion that the Sun goes around the Earth.','reject/dismiss a notion Aristotle rejected the notion that the body and the soul are separate.','a vague notion (= an unclear idea ) He had only a vague notion of what might happen next.','an absurd/ridiculous notion They had the ridiculous notion that they could make a living from singing.','a simple notion You cannot rate the project according to a simple notion of ‘value for money’: there are too many factors involved.','an abstract notion In art, how can you represent abstract notions such as peace or justice?','a romantic notion (= one that is based on how you want something to be, not how it is in real life ) He rejected the romantic notion of rugby as a game for gentlemen.','a preconceived notion (= an idea that you have before you have enough knowledge or experience ) The police were accused of twisting the evidence to meet their preconceived notion of his guilt.','an accepted/received notion (= an idea that most people believe ) These women challenged accepted notions of female roles in society.','the whole notion of something (= used to emphasize that you are talking about a lot of related ideas, not just one specific idea ) The movie makes us question the whole notion of what makes a hero.','not have the faintest/foggiest notion (= not know or understand something at all ) He had not the foggiest notion how far he might have to walk.']::text[],'[]'::jsonb,0),
('b76c00c8-231d-54f7-a93b-c6cc5e4434b7','ff13fb44-a0c5-566a-acd2-4fc24dc1352b',1,'number','شماره','spoken & written','a word or sign that represents an exact amount or quantity','[ countable ]',null,'عدد، شماره؛ تعداد؛ شماره (تلفن)؛ عدد (موزیک)','{}'::text[],'{}'::text[],array['a lucky number (= a number you think gives you good luck ) Three is my lucky number.','an even number (= 2,4, 6,8 etc ) All even numbers can be divided by 2.','an odd number (= 1,3, 5,7 etc ) You can’t work in pairs if you’ve got an odd number of people.','a round number (= a number ending in zero ) A hundred is a nice round number.','a positive number (= a number that is more than zero ) Maths is easier if you are dealing with positive numbers.','a negative/minus number (= a number that is less than zero ) Can a negative number have a square root?','a prime number (= a number such as 13 that can be divided only by itself and 1 ) After 7, what is the next prime number?','a cardinal number (= a number such as 1,2, or 3 that shows how many of something there are ) Numbers go on to infinity, so there is no last cardinal number.','an ordinal number (= a number such as 1st, 2nd, or 3rd that shows where something comes in a series or list ) The children learn about position and ordinal numbers when they stand in a line.','a whole number (= a number that is not a fraction )','add numbers together Add the two numbers together and divide by three.','add up numbers (= add several numbers together ) Write all the numbers down, then add them up.','subtract one number from another Subtract this number from the total.','multiply one number by another What happens if you multiply a positive number by a negative number?','divide one number by another You can’t divide a prime number by any other number, except 1.']::text[],'[{"sentence":"They wrote various numbers on a large sheet of paper.","translation":"آنها اعداد مختلفی را روی یک کاغذ بزرگ نوشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001784211.mp3"},{"sentence":"Add all the numbers together.","translation":"همه اعداد را با هم جمع کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001104.mp3"},{"sentence":"A hundred pounds is a good round number.","translation":"صد پوند عدد گرد خوبی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001105.mp3"},{"sentence":"I’m no good with numbers.","translation":"من با اعداد خوب نیستم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001106.mp3"}]'::jsonb,4),
('b8ba2a80-6247-5966-a1d5-69bc490593ad','ff13fb44-a0c5-566a-acd2-4fc24dc1352b',2,'phone','تلفن','spoken & written','a phone number','[ countable ]',null,'یک شماره تلفن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My new number is 502–6155.","translation":"شماره جدید من 502–6155 است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000251329.mp3"},{"sentence":"I gave him my home number.","translation":"شماره خانه ام را به او دادم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000251332.mp3"},{"sentence":"What’s your mobile number?","translation":"شماره موبایلت چیه؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001784223.mp3"},{"sentence":"Sorry, you have the wrong number .","translation":"با عرض پوزش، شما شماره اشتباهی دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000251335.mp3"}]'::jsonb,4),
