('ac112d68-fc50-50d3-a52d-6d44c50995d5','b37cdafe-0416-542c-aa8a-7cf04b483031',1,null,null,'spoken & written','to feel or say that you oppose or disapprove of something','[ intransitive ]',null,'مخالفت کردن، اعتراض کردن (به)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"If no one objects, I would like Mrs Harrison to be present.","translation":"اگر کسی مخالفت نمی کند، دوست دارم خانم هریسون حضور داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000256594.mp3"},{"sentence":"Robson strongly objected to the terms of the contract.","translation":"رابسون به شدت به شرایط قرارداد اعتراض کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000256597.mp3"},{"sentence":"I objected to having to rewrite the article.","translation":"من با بازنویسی مقاله مخالفت کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000256600.mp3"},{"sentence":"Mr Chairman, I object. That is an unfair allegation.","translation":"آقای رئیس، من اعتراض دارم. این یک ادعای ناعادلانه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000256604.mp3"},{"sentence":"She objected to my suggestion.","translation":"او با پیشنهاد من مخالفت کرد.","audio_url":null}]'::jsonb,5),
('2911cceb-07a9-5c45-a13b-9d11097ecc3a','b37cdafe-0416-542c-aa8a-7cf04b483031',2,null,null,'spoken & written','to state a fact or opinion as a reason for opposing or disapproving of something','[ transitive ]',null,'بیان یک واقعیت یا نظر به عنوان دلیلی برای مخالفت یا عدم تایید چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The group objected that the policy would prevent patients from receiving the best treatment.","translation":"این گروه اعتراض کردند که این سیاست از دریافت بهترین درمان برای بیماران جلوگیری می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557395.mp3"},{"sentence":"‘My name’s not Sonny, ’ the child objected.","translation":"کودک مخالفت کرد: «اسم من سانی نیست».","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000256610.mp3"}]'::jsonb,2),
