('0becc6b4-97ea-5999-9431-a7af70e07087','822f3bf3-0a9b-5ee7-9e7a-a9ce36baf186',1,null,null,'spoken & written','to allow something to happen, especially by an official decision , rule, or law','[ transitive ]',null,'اجازه دادن، رخصت دادن (رسمی)؛ مجاز داشتن (قانون)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Smoking is only permitted in the public lounge.","translation":"سیگار کشیدن فقط در سالن عمومی مجاز است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351947.mp3"},{"sentence":"As a punishment, she was not permitted to attend any school activities.","translation":"به عنوان تنبیه، او اجازه شرکت در هیچ فعالیت مدرسه ای را نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351953.mp3"},{"sentence":"Dogs are not permitted inside the shop.","translation":"ورود سگ به مغازه ممنوع است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351956.mp3"},{"sentence":"The bill would permit workers 12 weeks of unpaid leave for family emergencies.","translation":"این لایحه به کارگران اجازه 12 هفته مرخصی بدون حقوق را برای مواقع اضطراری خانوادگی می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020169.mp3"},{"sentence":"He had more than the permitted level of alcohol in his blood.","translation":"او بیش از حد مجاز الکل در خونش داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560150.mp3"},{"sentence":"His parents won’t let him watch TV after ten o''clock.","translation":"والدینش به او اجازه نمی دهند بعد از ساعت ده تلویزیون تماشا کند.","audio_url":null}]'::jsonb,6),
('02ce9c19-1619-5818-8a0b-50d0ec4bdf75','822f3bf3-0a9b-5ee7-9e7a-a9ce36baf186',2,null,null,'spoken & written','to make it possible for something to happen','[ intransitive, transitive ]',null,'تا امکان وقوع چیزی را فراهم کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The large windows permit a clear view of the lake.","translation":"پنجره های بزرگ امکان دید واضحی از دریاچه را فراهم می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560151.mp3"},{"sentence":"The moon permitted me to see a little way into the distance.","translation":"ماه به من اجازه داد تا کمی دورتر را ببینم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560154.mp3"},{"sentence":"I’ll see you after the meeting, if time permits (= if it finishes early enough ) .","translation":"اگر زمان اجازه دهد، شما را بعد از جلسه می بینم (= اگر به اندازه کافی زود تمام شود).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351961.mp3"},{"sentence":"We’ll have a picnic at the beach, weather permitting (= if the weather is good enough ) .","translation":"اگر آب و هوا اجازه دهد، در ساحل یک پیک نیک خواهیم داشت (= اگر هوا به اندازه کافی خوب باشد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351967.mp3"}]'::jsonb,4),
('c52048e1-1832-515d-9574-d066b9d793d8','c09a1c5d-a9fd-52c2-a1bb-0e775c470548',1,null,null,'spoken & written','an official written statement giving you the right to do something',null,null,'یک بیانیه کتبی رسمی که به شما حق انجام کاری را می دهد','{}'::text[],'{}'::text[],array['have a permit Do you have a resident''s parking permit?','need/require a permit EU citizens no longer need a permit to work in the UK.','get a permit You have to get a special permit in order to visit the Saiq plateau.','issue a permit Up to ten fishing permits are issued each day.','obtain a permit (= more formal than ''get'' ) Hunters are required to obtain a permit.','apply for a permit Farmers must apply for permits to use the new chemicals.','a work permit She had problems getting a work permit for the States.','a parking permit You’ll need to apply for a residential parking permit.','a travel permit Palestinians have to obtain a travel permit for travel between the West Bank and the Gaza Strip.','a residence permit ( also residency permit especially American English ) (= one that allows you to live in a country ) Residence permits will be limited to five years.','an export permit An export permit is required for the export of this timber.','a gun permit More than 300,000 civilians, in a country of 6 million, have gun permits.','a fishing permit To fish you’ll need a rod licence and a fishing permit.']::text[],'[{"sentence":"A permit is required for fishing in the canal.","translation":"برای ماهیگیری در کانال مجوز لازم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000352472.mp3"},{"sentence":"Hikers need a camping permit for overnight stays in the park.","translation":"کوهنوردان برای اقامت شبانه در پارک به مجوز کمپینگ نیاز دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000352475.mp3"}]'::jsonb,2),
('37d5f39a-cad2-5141-b67c-c219516a6dd7','39f5729a-19ae-5513-b6f2-af22159ba2a1',1,null,null,'spoken & written','a human being, especially considered as someone with their own particular character',null,null,'شخص، فرد؛ شخصیت (فرد)؛ قلم (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was a very nice person, always pleasant and friendly.","translation":"او فردی بسیار خوب، همیشه خوش برخورد و صمیمی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353017.mp3"},{"sentence":"The only person who really said anything helpful was Jack.","translation":"تنها کسی که واقعاً چیز مفیدی گفت جک بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584425.mp3"},{"sentence":"David was not the sort of person who found it easy to talk about his feelings.","translation":"دیوید از آن دسته افرادی نبود که به راحتی در مورد احساسات خود صحبت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584428.mp3"},{"sentence":"I like her as a person , but not as a boss.","translation":"من او را به عنوان یک شخص دوست دارم، اما نه به عنوان یک رئیس.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353019.mp3"},{"sentence":"I still know quite a lot of people in the village.","translation":"من هنوز افراد زیادی را در روستا می شناسم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353020.mp3"},{"sentence":"a group of young people","translation":"گروهی از جوانان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584432.mp3"},{"sentence":"I’m not a morning person.","translation":"من آدم صبح نیستم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353031.mp3"}]'::jsonb,7),
