('dd3e9e06-b375-58f5-b549-696a242d904a','7fc99130-cc3d-5046-9d19-d26d5722233e',1,null,null,'spoken & written','to like someone or something more than someone or something else, so that you would choose it if you could',null,null,'ترجیح دادن، بیشتر خواستن (یکی بر دیگری)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This type of owl prefers a desert habitat.","translation":"این نوع جغد زیستگاه بیابانی را ترجیح می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568251.mp3"},{"sentence":"She prefers her coffee black.","translation":"او قهوه مشکی خود را ترجیح می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568252.mp3"},{"sentence":"the government’s preferred option","translation":"گزینه مطلوب دولت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568253.mp3"},{"sentence":"a child that prefers his imaginary world to reality","translation":"کودکی که دنیای خیالی خود را به واقعیت ترجیح می دهد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000321518.mp3"},{"sentence":"Employees said they would prefer more flexible working hours.","translation":"کارمندان گفتند که ساعات کاری انعطاف پذیرتری را ترجیح می دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000321515.mp3"},{"sentence":"I prefer to wear clothes made of natural fibers.","translation":"من ترجیح می دهم لباس هایی از الیاف طبیعی بپوشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000321521.mp3"},{"sentence":"Or, if you prefer , you can email us.","translation":"یا در صورت تمایل می توانید به ما ایمیل بزنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568260.mp3"},{"sentence":"Chantal prefers travelling by train.","translation":"شانتال سفر با قطار را ترجیح می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000321524.mp3"},{"sentence":"We prefer that our teachers have a degree in early childhood education.","translation":"ما ترجیح می دهیم که معلمان ما دارای مدرک تحصیلی در دوران کودکی باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568268.mp3"}]'::jsonb,9),
